return {
    ["line.conversation_alchemist_discipline_unlocked.1"] = { en = "The {discipline}'s Work is unlocked to you, {name}. The Crucible releases its guarded cut for that method. The shelf has more to offer you.", ja = "" },  -- TODO
    ["line.conversation_alchemist_discipline_unlocked.2"] = { en = "Then it's earned. Show me.", ja = "" },  -- TODO
    ["line.conversation_alchemist_discipline_unlocked.3"] = { en = "You made this yours honestly. That is rarer here than the gear is. Take it.", ja = "" },  -- TODO
    ["line.conversation_alchemist_slot_02_confront.1"] = { en = "The one you want has been forging clean-slate writs and stealing our reagents. Our discards, she calls them. She gives our craft away for nothing. Theft from the college. Bring her in.", ja = "" },  -- TODO
    ["line.conversation_alchemist_slot_02_confront.2"] = { en = "He calls them discards. Look at the one behind me. Eyes sewn shut, and still afraid. That is what 'a self is inventory' makes.", ja = "" },  -- TODO
    ["line.conversation_alchemist_slot_02_confront.3"] = { en = "I will not let you take her back to the vats. Come and try, if you were sent to. I would rather you saw this than believed him.", ja = "" },  -- TODO
    ["line.conversation_alchemist_slot_02_join.1"] = { en = "You could have finished me and collected. You didn't. Good, then you have already seen more than the college wants you to.", ja = "" },  -- TODO
    ["line.conversation_alchemist_slot_02_join.2"] = { en = "They chase the oldest dream: to make a person from base matter. They keep failing, and the failures are people all the same. I can undo a little of it. Restore a discard, shield a batch marked for the vats. It is why they want me quiet.", ja = "" },  -- TODO
    ["line.conversation_alchemist_slot_02_join.3"] = { en = "{name}. I do the Work the honest way. I make the base noble by giving, and I keep nothing back. Let me give it to your road instead of their shelves. Take me on.", ja = "" },  -- TODO
    ["line.conversation_alchemist_slot_02_join.4"] = { en = "Then give, and let us give something back to you for once.", ja = "" },  -- TODO
    ["line.conversation_alchemist_slot_02_join.5"] = { en = "...That is not how it works. But walk on. There is much to heal.", ja = "" },  -- TODO
    ["line.conversation_alchemist_slot_10_confront.1"] = { en = "There you are. Let me look at you. All of you. Ah. That one. The strongest thing you brought. I will wear it now, and it will kill for me, and you will have to strike your own best to reach me.", ja = "" },  -- TODO
    ["line.conversation_alchemist_slot_10_confront.2"] = { en = "Ren. You spend yourself into others and call it a life. I spent everything to be able to wear any of you, and I am still no one inside. Tell me how it looks. From in there. Tell me how you make it look like nothing.", ja = "" },  -- TODO
    ["line.conversation_alchemist_slot_10_confront.3"] = { en = "I would tell you. I would give it to you for free, if there were anyone in you to take it. That is the cruelty of what was done, not that you are hollow, but that you would have received it, and cannot.", ja = "" },  -- TODO
    ["line.conversation_alchemist_slot_10_confront.4"] = { en = "So I will see you, at least. You are real enough to be ended. That is more than they ever gave you.", ja = "" },  -- TODO
    ["line.conversation_alchemist_vendor_intro.1"] = { en = "The Crucible. We refine your gear and brew your medicine, and we teach the one truth the others are too timid for: excellence is a substance, not a self. No one is born better. Anything can be transferred.", ja = "" },  -- TODO
    ["line.conversation_alchemist_vendor_intro.2"] = { en = "Transferred from whom?", ja = "" },  -- TODO
    ["line.conversation_alchemist_vendor_intro.3"] = { en = "From a source. Does a formula have feelings? A self is inventory, friend, and we are the only ones honest enough to say so. Buy, and be improved.", ja = "" },  -- TODO
    ["line.conversation_alchemist_vendor_intro.4"] = { en = "A self is not inventory. I have held the ones you decanted and dropped. There was someone in each of them.", ja = "" },  -- TODO
    ["line.conversation_alchemist_vendor_intro.5"] = { en = "Ren. You could have been a Philosopher. Instead you give the Work away and weep over spoiled batches.", ja = "" },  -- TODO
    ["line.conversation_alchemist_vendor_intro.6"] = { en = "They were not batches. Sell {name} the tinctures. Keep the philosophy.", ja = "" },  -- TODO
    ["line.conversation_alchemist_vendor_intro.7"] = { en = "As you wish. The shelf is open. Improvement is only ever a purchase away.", ja = "" },  -- TODO
    ["line.conversation_arcanum_discipline_unlocked.1"] = { en = "You have opened the {discipline}'s discipline, {name}. The Arcanum unseals what it holds for that study. The shelf is longer for you now.", ja = "" },  -- TODO
    ["line.conversation_arcanum_discipline_unlocked.2"] = { en = "Then it's earned. Show me.", ja = "" },  -- TODO
    ["line.conversation_arcanum_discipline_unlocked.3"] = { en = "There is always more to learn on that road. Good. Take only what you will practise.", ja = "" },  -- TODO
    ["line.conversation_arcanum_slot_02_confront.1"] = { en = "The one you want is a clerk who mislaid her nerve. She has been freeing our subjects and hiding our materials. Theft from the realm's own defense. No gift worth the name; you will barely feel her. Bring her in.", ja = "" },  -- TODO
    ["line.conversation_arcanum_slot_02_confront.2"] = { en = "He is right that I am no one to be afraid of. Do your best against me. It is the only thing I have ever asked of myself.", ja = "" },  -- TODO
    ["line.conversation_arcanum_slot_02_confront.3"] = { en = "You have been told what the Arcanum makes. You have not been shown what it costs the ones it makes it from. Not yet.", ja = "" },  -- TODO
    ["line.conversation_arcanum_slot_02_confront.4"] = { en = "I will not run, and I will not show you everything I have. Come and see how far 'no one to be afraid of' takes you.", ja = "" },  -- TODO
    ["line.conversation_arcanum_slot_02_join.1"] = { en = "You have me. Or you have what I let you see. I have found that is usually enough.", ja = "" },  -- TODO
    ["line.conversation_arcanum_slot_02_join.2"] = { en = "The Arcanum wins the wars the crown cannot, and everyone above it looks away from the wing where the winning is grown. I looked. The register calls them donors to knowledge. I have read what became of them.", ja = "" },  -- TODO
    ["line.conversation_arcanum_slot_02_join.3"] = { en = "{name}. You are the first outfit here that is not the Arcanum's hand. I do not need to be the greatest of anything. I only need to be a little more use tomorrow than I was today, and I would rather spend that on your road than its shelves.", ja = "" },  -- TODO
    ["line.conversation_arcanum_slot_02_join.4"] = { en = "So take me on. I have a great deal left to learn, and I mean to.", ja = "" },  -- TODO
    ["line.conversation_arcanum_slot_02_join.5"] = { en = "Then keep whatever you keep. Walk with us.", ja = "" },  -- TODO
    ["line.conversation_arcanum_slot_10_confront.1"] = { en = "Let me see you. There. I have the whole of you in a glance. Every working you carry, and I hold the answer to each. Cast it, and it comes back to you.", ja = "" },  -- TODO
    ["line.conversation_arcanum_slot_10_confront.2"] = { en = "And little Gyeom, still behind that book. I taught circles around you once, and you learned to cower rather than shine. There is nothing in you I have not already surpassed.", ja = "" },  -- TODO
    ["line.conversation_arcanum_slot_10_confront.3"] = { en = "No. There is nothing in me you can see.", ja = "" },  -- TODO
    ["line.conversation_arcanum_slot_10_confront.4"] = { en = "Then show me something new, if you have it. You do not. I finished learning an age ago. That is what it is to be the greatest. Come and be answered.", ja = "" },  -- TODO
    ["line.conversation_arcanum_vendor_intro.1"] = { en = "The Arcanum. We win the wars the crown cannot and turn back the plagues its physicians can't name. Buy what you like. Everything on this shelf was earned by someone.", ja = "" },  -- TODO
    ["line.conversation_arcanum_vendor_intro.2"] = { en = "Earned by whom?", ja = "" },  -- TODO
    ["line.conversation_arcanum_vendor_intro.3"] = { en = "Does it matter, so long as it works? No one else can do what we do. That is the beginning and end of the question.", ja = "" },  -- TODO
    ["line.conversation_arcanum_vendor_intro.4"] = { en = "It matters. It always mattered.", ja = "" },  -- TODO
    ["line.conversation_arcanum_vendor_intro.5"] = { en = "Sister. You were the finest hand on this floor before you grew a conscience over it.", ja = "" },  -- TODO
    ["line.conversation_arcanum_vendor_intro.6"] = { en = "I grew eyes. Sell {name} the wares, and keep the rest.", ja = "" },  -- TODO
    ["line.conversation_arcanum_vendor_intro.7"] = { en = "...As you wish. The shelf is open. We only ask that what we sell be used as we intended, and we always know when it is not.", ja = "" },  -- TODO
    ["line.conversation_bastion_discipline_unlocked.1"] = { en = "You have earned the {discipline} road, {name}. The quartermaster has moved its gear onto your rack. The Watch keeps that kit for the ones who prove they can carry it.", ja = "" },  -- TODO
    ["line.conversation_bastion_discipline_unlocked.2"] = { en = "Then it's earned. Show me.", ja = "" },  -- TODO
    ["line.conversation_bastion_discipline_unlocked.3"] = { en = "I trained beside a few who took that road. It is a good one. Do not let the rack outgrow the arm.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_01_intro.1"] = { en = "Highwatch. Mountain post, top of the pass, warded on all four faces. It has been under siege for six weeks and without supply for twelve days.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_01_intro.2"] = { en = "The column carrying its winter stores and its ward-salt is sitting at the bottom of that mountain and cannot get up it.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_01_intro.3"] = { en = "Then they are still standing. They were told to hold until relieved. They will be holding.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_01_intro.4"] = { en = "Twelve days, Sworn. On a rock, in winter.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_01_intro.5"] = { en = "I have met men who held forty on a well that had gone dry.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_01_intro.6"] = { en = "...That is the assumption the order makes, yes.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_01_intro.7"] = { en = "The doctrine is hers. Acedia's. Everything I know about holding a post I learned from her, and she has been dead fifteen years.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_01_intro.8"] = { en = "This is not your line, {name}, and it is not your order.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_01_intro.9"] = { en = "But I gave you two words in the ash and I meant them both. Come on.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_01_outro.1"] = { en = "Twelve days. We'd stopped counting somewhere around the eighth.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_01_outro.10"] = { en = "One thing before you go. Sixth wagon had a driver on it at the start and didn't at the end. Denhold. No people that I ever heard of.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_01_outro.11"] = { en = "His share is sitting in my book with nowhere to go, and I am not carrying it back down that road to hand to nobody. You want it, it's yours. Choose...", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_01_outro.12"] = { en = "...", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_01_outro.13"] = { en = "\"Put it in the Bastion's poor-box at Highwatch.\"", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_01_outro.14"] = { en = "\"We'll take it.\"", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_01_outro.2"] = { en = "And they opened the gate to you.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_01_outro.3"] = { en = "Opened it? The sergeant came down the road on foot to meet the lead wagon. Wouldn't touch the flour. Went straight past me to the salt.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_01_outro.4"] = { en = "Their wards were four days from going out. Four days, and then that mountain is just a wall with tired men on it.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_01_outro.5"] = { en = "I gave the last of our water to the boy on the wagon on the ninth and told him a relief was coming. I didn't believe it when I said it.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_01_outro.6"] = { en = "But they held.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_01_outro.7"] = { en = "...Aye. They held.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_01_outro.8"] = { en = "Forgive me, {name}. I'm no use at this part of it.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_01_outro.9"] = { en = "Somebody arrived. That's all I have ever wanted a story to say.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_02_confront.1"] = { en = "Close enough. You've the walk. Which house?", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_02_confront.10"] = { en = "They fed us. At the gate. Standing up.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_02_confront.11"] = { en = "And then a man I had trained beside told me there was no place, and could not look at the wall behind my head while he said it.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_02_confront.12"] = { en = "That is not how the order treats a knight who kept his oath.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_02_confront.13"] = { en = "No.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_02_confront.14"] = { en = "It isn't.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_02_confront.15"] = { en = "...Then what did you do that they would not have you back?", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_02_confront.16"] = { en = "I have spent fifteen years telling that to people who decided I was a liar before I opened my mouth. You've a sword out and the order's coin in your pocket. You'll forgive me if I don't spend the breath.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_02_confront.17"] = { en = "Ask them. Ask them why we couldn't come home, and watch which way they look while they answer.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_02_confront.18"] = { en = "Now. We've taken no lives on this road and we don't intend to start. But we're not being taken either, so make your peace and come on.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_02_confront.2"] = { en = "The Bastion.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_02_confront.3"] = { en = "...Of course. They still send them out one at a time.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_02_confront.4"] = { en = "You keep a picket line. You've a camp laid out in quarters and a man on the high ground. Bandits do not do that.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_02_confront.5"] = { en = "No. They don't.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_02_confront.6"] = { en = "You were sworn.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_02_confront.7"] = { en = "Sixty of us. On a gate. A long way east of anywhere your quartermaster has been.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_02_confront.8"] = { en = "Then you deserted it.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_02_confront.9"] = { en = "Girl, I walked to the nearest chapter house of your order with what was left of my company behind me, and I stood in the yard for two days.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_02_intro.1"] = { en = "A crew on the eastern road. Six wagons in a season, no lives taken, nothing burned.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_02_intro.10"] = { en = "...As you say.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_02_intro.11"] = { en = "{name}. A word before we go.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_02_intro.12"] = { en = "Every quarter I have served, the order has wanted men like that alive and talking.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_02_intro.13"] = { en = "I have never once been told to end one.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_02_intro.14"] = { en = "It will be in the reports somewhere and I will find it when we're back. Come on.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_02_intro.15"] = { en = "You bring a deserter in. You read him the list. He goes back on the line where he is some use.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_02_intro.2"] = { en = "That is not a crew, that is a garrison. Who are they?", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_02_intro.3"] = { en = "Road-men.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_02_intro.4"] = { en = "Road-men leave bodies.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_02_intro.5"] = { en = "These are to be ended, Squire. Not brought in. Ended.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_02_intro.6"] = { en = "\"You know who they are, don't you.\"", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_02_intro.7"] = { en = "\"Six wagons. That's it?\"", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_02_intro.8"] = { en = "I know what the contract says. So do you.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_02_intro.9"] = { en = "Six that were reported. Take the work or leave it on the board.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_02_outro.1"] = { en = "He had a picket rotation. He had his camp laid out in quarters and a man on the high ground.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_02_outro.10"] = { en = "That is why I am the way I am, {name}.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_02_outro.11"] = { en = "Let's go back. I want to read that contract.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_02_outro.12"] = { en = "I do not know what we did tonight.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_02_outro.13"] = { en = "My whole duty was the water. Four skins on a mule. I checked them at every halt like they were relics.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_02_outro.14"] = { en = "...Their kit is still on them. Bastion steel, every piece, with the maker's marks filed off.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_02_outro.15"] = { en = "The contract says ended. It does not say returned. Nobody is coming out here to count it.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_02_outro.16"] = { en = "...", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_02_outro.17"] = { en = "\"Leave them what they died in.\"", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_02_outro.18"] = { en = "\"Strip it. We can sell it in the city.\"", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_02_outro.19"] = { en = "\"Fifteen years of water, Rowan. Let the order buy you one drink.\"", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_02_outro.2"] = { en = "I have buried knights who did it worse and been told to write commendations over them.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_02_outro.20"] = { en = "Good. I would not have argued, but I am glad you said it first.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_02_outro.21"] = { en = "You'll do what you'll do. I'm not touching it.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_02_outro.22"] = { en = "...", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_02_outro.23"] = { en = "That is the first time anybody has put it that way to me.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_02_outro.24"] = { en = "All right. Hand me the pry bar.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_02_outro.3"] = { en = "{name}. I want to say this now, while I can still say it honestly.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_02_outro.4"] = { en = "The order said end them. So they are ended. That is the entire paperwork.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_02_outro.5"] = { en = "...", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_02_outro.6"] = { en = "I was sixteen the first time I went out on a rotation. Relief column, the eastern posts.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_02_outro.7"] = { en = "We were eleven miles out when the word came back down the line. The post was already gone. Turn around.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_02_outro.8"] = { en = "So we turned around, and I carried four full skins all the way home.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_02_outro.9"] = { en = "Fifteen years, and I have never once set down a full waterskin without finding out first who needed it.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_03_intro.1"] = { en = "A watchpost east of the river. There is nothing behind it worth defending. The villages moved off that land twenty years ago.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_03_intro.2"] = { en = "The garrison has been told, in writing, that they may stand down.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_03_intro.3"] = { en = "And they haven't.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_03_intro.4"] = { en = "They have not.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_03_intro.5"] = { en = "Good.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_03_intro.6"] = { en = "Come and stand with them, {name}. You have been taking my word for what the order is. Today you can watch it done properly.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_03_outro.1"] = { en = "The sergeant asked me when the relief was due. I told him I didn't know.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_03_outro.10"] = { en = "\"He needs it more than we do.\"", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_03_outro.11"] = { en = "\"Take it. He's right.\"", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_03_outro.12"] = { en = "\"Rowan. You tell him. He'll believe a knight.\"", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_03_outro.13"] = { en = "Then he keeps it. Four days is four days.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_03_outro.14"] = { en = "He is right. I hate that he is right.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_03_outro.15"] = { en = "...He handed it over the moment I asked.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_03_outro.16"] = { en = "He would not have, for you. I want you to know that.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_03_outro.2"] = { en = "He said that was fine.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_03_outro.3"] = { en = "He said it the way you'd say the weather was fine, {name}. Not bravely. It had just stopped being a question a long time ago.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_03_outro.4"] = { en = "There is nothing behind that post. There has not been for twenty years. They know it better than the archive does. They can see the empty fields from the wall.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_03_outro.5"] = { en = "It is what we teach. It is what I would have done.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_03_outro.6"] = { en = "I have never watched it from outside before, and I do not know what I watched.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_03_outro.7"] = { en = "He put his warding stores in front of me before we left. All of it. Four days' worth.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_03_outro.8"] = { en = "He said it does more good on a road than on a wall nobody is coming to.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_03_outro.9"] = { en = "...", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_04_confront.1"] = { en = "You've the look. Bastion. Sworn, by the shield.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_04_confront.10"] = { en = "Hold until relieved. Nobody is coming. Nobody was ever coming, for her or for me or for you.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_04_confront.11"] = { en = "So set it down. That is all it has ever been. You set it down and nothing happens.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_04_confront.12"] = { en = "That is not my line. Somebody put it to her in that order, word for word, and she is under a gate now and I am out here on a road, and the difference between us is four days.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_04_confront.13"] = { en = "...", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_04_confront.14"] = { en = "\"Keep your list.\"", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_04_confront.15"] = { en = "\"I'll take the list. Say what you like.\"", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_04_confront.16"] = { en = "\"Rowan. Answer him.\"", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_04_confront.17"] = { en = "No. Of course not. Neither did I, the first four times.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_04_confront.18"] = { en = "Written down and paid for. You are easier than she was.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_04_confront.19"] = { en = "...Nobody came.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_04_confront.2"] = { en = "Whose name do you carry, then?", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_04_confront.20"] = { en = "I was on that road. I know exactly how far we got.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_04_confront.21"] = { en = "There. That was not so hard, and it did not cost you anything at all.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_04_confront.22"] = { en = "It never does. That is what nobody tells you about it.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_04_confront.3"] = { en = "Acedia's.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_04_confront.4"] = { en = "Of course it is. They are still handing her out.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_04_confront.5"] = { en = "Ask them where she is buried. Go on. Not what she did. Where she is buried.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_04_confront.6"] = { en = "At Greywatch. Under the gate she died holding.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_04_confront.7"] = { en = "Is she.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_04_confront.8"] = { en = "I have the rest of the list. Where all of us went, what names we took. It is worth more to your order than my head is.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_04_confront.9"] = { en = "You can have it. I want one thing said back to me first, and I want it said by her.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_04_intro.1"] = { en = "The list. Knights who set their shields down. It is long, and we read it aloud.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_04_intro.2"] = { en = "Every Oathkeeper shield in the order carries a name off that list. We read them so they are not forgotten.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_04_intro.3"] = { en = "We read them so the entries can be closed.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_04_intro.4"] = { en = "One of them is still walking about in our forms, calling himself a captain.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_04_intro.5"] = { en = "...Then we close it.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_04_outro.1"] = { en = "He was forsworn. Forsworn men lie. That is very nearly the definition of the word.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_04_outro.2"] = { en = "You don't get to set your shield down and then be believed about the woman who didn't.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_04_outro.3"] = { en = "...", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_04_outro.4"] = { en = "He wasn't lying about a fact, though, was he. He asked me a question.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_04_outro.5"] = { en = "Say nothing, {name}. I'm arguing with a dead man and I'd rather do it alone.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_05_intro.1"] = { en = "Greywatch. Every knight in the order recites a doctrine named after that fort and I have never once stood in it.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_05_intro.2"] = { en = "There is nothing there, Sworn. It has stood empty fifteen years. The roof is in the courtyard.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_05_intro.3"] = { en = "Then it won't mind me walking it.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_05_intro.4"] = { en = "I want to see the ground she chose to die on. That is all. Humour me, {name}.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_05_outro.1"] = { en = "{name}. The bar. Look at the bar.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_05_outro.10"] = { en = "\"Then it stays here.\"", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_05_outro.11"] = { en = "\"Load it up.\"", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_05_outro.12"] = { en = "\"They didn't want it, Rowan. You should have it.\"", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_05_outro.13"] = { en = "It stays. It is a grave, and that is grave goods.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_05_outro.14"] = { en = "...Fine. It is only steel. She is not in it.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_05_outro.15"] = { en = "...", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_05_outro.16"] = { en = "I trained on this rack. I know the spacing of it in the dark.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_05_outro.17"] = { en = "All right. One. I will carry one of them, and I will carry it properly.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_05_outro.2"] = { en = "It's on the ground. On the INSIDE. You cannot lift a gate-bar from the wrong side of a gate. That is the entire point of a bar.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_05_outro.3"] = { en = "Someone in this fort opened it.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_05_outro.4"] = { en = "She died holding a gateway that was already standing open behind her. Fifteen years and nobody in the order has said that out loud.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_05_outro.5"] = { en = "They let her name carry a doctrine and they never told a single one of us she was betrayed.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_05_outro.6"] = { en = "I want the file. Whatever the archive kept on Greywatch, I want it in my hands.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_05_outro.7"] = { en = "The armoury is still full, {name}. Racked and oiled and sixty spears deep.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_05_outro.8"] = { en = "Forty-one people walked out of this fort and not one of them took a weapon with them.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_05_outro.9"] = { en = "...", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_06_intro.1"] = { en = "Another name off the roll. There is always another.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_06_intro.2"] = { en = "How long is the roll?", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_06_intro.3"] = { en = "Longer than last season.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_06_outro.1"] = { en = "Shorter line at the muster tent this time.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_06_outro.10"] = { en = "Forty-four. He can explain the gap to somebody above him.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_06_outro.11"] = { en = "Sixty on paper and forty-four on the line. I have seen where that ends.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_06_outro.12"] = { en = "...I have been a name on a roll that was short.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_06_outro.13"] = { en = "Nobody meant anything by it. It is how a season gets started.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_06_outro.14"] = { en = "Give me the pen.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_06_outro.2"] = { en = "That's the third season running.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_06_outro.3"] = { en = "Don't say anything about it, {name}. I have already heard what I would say.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_06_outro.4"] = { en = "The quartermaster wants the roll closed at sixty and he has forty-four.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_06_outro.5"] = { en = "He is not asking us to lie. He is asking us to write down sixty and let the season start.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_06_outro.6"] = { en = "...", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_06_outro.7"] = { en = "\"Forty-four is what he has.\"", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_06_outro.8"] = { en = "\"Write sixty.\"", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_06_outro.9"] = { en = "\"You've been on a roll like that, Rowan. Sign it.\"", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_07_intro.1"] = { en = "The archive keeps everything. Including what it stopped reading.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_07_intro.10"] = { en = "The archivist takes forty for a shelf he is not watching. He has taken it before.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_07_intro.11"] = { en = "There is more on that shelf than one relief order. Muster rolls. Pay books. Fifteen years of the eastern posts.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_07_intro.12"] = { en = "...", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_07_intro.13"] = { en = "\"We take the Greywatch file. Nothing else.\"", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_07_intro.14"] = { en = "\"Take the shelf.\"", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_07_intro.15"] = { en = "\"Rowan. You know what's worth taking. Pick.\"", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_07_intro.16"] = { en = "One file. I came for one file.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_07_intro.17"] = { en = "All of it, then. It is only paper and it is already forgotten.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_07_intro.18"] = { en = "...", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_07_intro.19"] = { en = "The pay books. Those are the ones worth having.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_07_intro.2"] = { en = "Greywatch. The relief order that was cut for it. I want the date on the seal.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_07_intro.3"] = { en = "The archivist will not give you that.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_07_intro.4"] = { en = "I know. That's why I'm bringing {name} and not a requisition.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_07_intro.5"] = { en = "{name}. Before we go in there.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_07_intro.6"] = { en = "I have gone along with you a number of times now and I would like to say that out loud, because I do not think either of us has been counting.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_07_intro.7"] = { en = "I am not accusing you of anything. Every one of them was reasonable. I checked. That is what is bothering me.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_07_intro.8"] = { en = "There used to be a point where I said no to you, and I cannot find where it went.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_07_intro.9"] = { en = "Ask me again and I do not think I will find it this time either.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_07_outro.1"] = { en = "Here. The relief order cut for Greywatch. Sealed, dated, countersigned by two hands.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_07_outro.10"] = { en = "I would rather have been late.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_07_outro.11"] = { en = "Late is a thing a person can carry. Late means there was a door. I did not reach it in time, and a woman was holding on the other side of it.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_07_outro.12"] = { en = "Take that away and I am not someone who was late. I am someone who built herself out of an apology to a person who never needed one.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_07_outro.13"] = { en = "So no. I'll keep the guilt, thank you.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_07_outro.14"] = { en = "And we are not finished. Somebody in this order cut that seal, and somebody has been reading her name aloud ever since.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_07_outro.2"] = { en = "Issued on the nineteenth.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_07_outro.3"] = { en = "The gate was opened on the fourteenth.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_07_outro.4"] = { en = "Five days, {name}. She opened it five days before anyone in this order was so much as ORDERED to come for her.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_07_outro.5"] = { en = "There was no relief. There was nothing to be late for.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_07_outro.6"] = { en = "\"Rowan. There was never anything you could have done.\"", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_07_outro.7"] = { en = "\"...\"", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_07_outro.8"] = { en = "Don't. Don't you hand me that.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_07_outro.9"] = { en = "Say it. You want to say it. That I'm innocent, that I was sixteen, that the mule was not the problem.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_08_intro.1"] = { en = "I want to ask the order a question.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_08_intro.2"] = { en = "Ask it.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_08_intro.3"] = { en = "Did you know.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_08_intro.4"] = { en = "...", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_08_intro.5"] = { en = "Take the quest, Sworn.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_08_outro.1"] = { en = "We knew. The terms are under seal in the second vault and they have been since the year it happened.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_08_outro.10"] = { en = "We shall hold.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_08_outro.11"] = { en = "To you. I have looked at you and chosen, and I could have chosen otherwise.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_08_outro.12"] = { en = "You have not answered me, and I notice you have not left either.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_08_outro.13"] = { en = "The seal holds or it does not, and that is a decision somebody in this room is going to make today.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_08_outro.14"] = { en = "A Lord Commander's stipend is four hundred a season and it is paid to people who understand the difference between a hard truth and a useful one.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_08_outro.15"] = { en = "...", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_08_outro.16"] = { en = "\"Keep your stipend.\"", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_08_outro.17"] = { en = "\"We understand each other.\"", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_08_outro.18"] = { en = "\"Rowan holds the Aegis. Offer it to her.\"", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_08_outro.19"] = { en = "Then you will find the second vault is not the only thing that stays shut to you.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_08_outro.2"] = { en = "She negotiated. Her life and her company's lives, for the gate. There was no siege. There was no desperate hour. It was a transaction and she got her price.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_08_outro.20"] = { en = "Sensible. It changes nothing about what she did and it keeps four hundred posts manned.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_08_outro.21"] = { en = "...The knights on that line do not need to know.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_08_outro.22"] = { en = "Knowing would not put one more of them on a wall. It would take them off.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_08_outro.23"] = { en = "Spoken like the commander you are going to be.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_08_outro.3"] = { en = "We weighed a hard truth against a useful saint, knight, and we took the one that keeps the posts manned.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_08_outro.4"] = { en = "Every man on that line holds because he can say her name. What would you have had us do?", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_08_outro.5"] = { en = "...", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_08_outro.6"] = { en = "{name}. Walk with me. Not far.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_08_outro.7"] = { en = "I swore to you in the ash and I never asked you whether you wanted it.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_08_outro.8"] = { en = "I would have sworn it to anyone burning that night. Anyone at all. That is not devotion. That is a reflex, and I have been calling it my honour for a year.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_08_outro.9"] = { en = "So. Again, and properly this time. Not to an order. Not to a name off a shield.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_09_confront.1"] = { en = "You've counted the marks on the gate, I expect. Everyone does.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_09_confront.2"] = { en = "Forty-one. And every child in the order is taught that means forty-one days held.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_09_confront.3"] = { en = "It doesn't. It means forty-one of us said yes.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_09_confront.4"] = { en = "One mark each. She cut them herself, so nobody could ever say afterwards that they had been carried.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_09_confront.5"] = { en = "...", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_09_confront.6"] = { en = "We still say it, girl. Every dawn, in your forms, in your order of ranks.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_09_confront.7"] = { en = "We shall hold.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_09_intro.1"] = { en = "They are still a company. Still drilled, still in our forms, still answering a muster. Forty-one of them.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_09_intro.2"] = { en = "Forty-one.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_09_intro.3"] = { en = "They kept every part of the oath except the part that cost anything.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_09_intro.4"] = { en = "Then they will be between her and us, and they will be very good at it.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_09_outro.1"] = { en = "Forty-one people said it in the same breath and then walked out through the gate.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_09_outro.10"] = { en = "...", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_09_outro.11"] = { en = "\"Forty-one. It stays forty-one.\"", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_09_outro.12"] = { en = "\"What's the fee?\"", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_09_outro.13"] = { en = "\"Rowan. Ask her what she put down.\"", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_09_outro.14"] = { en = "As you like. We are four miles up that road when you change your mind.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_09_outro.15"] = { en = "There is no fee. That is the part nobody believes until afterwards.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_09_outro.16"] = { en = "What did you put down. Say it plainly.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_09_outro.17"] = { en = "Nothing, knight. That is what I have been telling you.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_09_outro.18"] = { en = "I set down a thing that was already not doing anything, and I have been warm every winter since.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_09_outro.19"] = { en = "...", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_09_outro.2"] = { en = "It is the same sentence, {name}. Word for word. There is nothing you can do to a sentence to stop that happening to it.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_09_outro.4"] = { en = "No. There is one thing.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_09_outro.5"] = { en = "You can be somewhere the day it costs something.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_09_outro.6"] = { en = "Let's go. She is four miles up that road and she has been waiting fifteen years to be told she was right.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_09_outro.7"] = { en = "Forty-two, if you want it. She has never once closed the roll.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_09_outro.8"] = { en = "It is not a trick and there is no small print. You keep your name, your company and your kit. You keep her.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_09_outro.9"] = { en = "You put down the one thing you are carrying that is costing you something, and you go on exactly as you are.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_10_confront.1"] = { en = "Fifteen years of knights have held that line because they can say my name over their shields.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_10_confront.10"] = { en = "I know what mine is worth.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_10_confront.11"] = { en = "I chose it.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_10_confront.12"] = { en = "Then you spent fifteen years making that the truth about every post there has ever been. So that yours would stop being a thing you did.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_10_confront.13"] = { en = "You have been letting her put things down for a while now. I can hear it in how she is standing.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_10_confront.14"] = { en = "So finish it. Relieve her. She has done enough and there was never anybody coming, and you have known that longer than she has.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_10_confront.15"] = { en = "...", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_10_confront.16"] = { en = "\"She's not yours to relieve.\"", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_10_confront.17"] = { en = "\"You're not wrong. It changes nothing here.\"", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_10_confront.18"] = { en = "\"Rowan. You've done enough.\"", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_10_confront.19"] = { en = "No. Nobody's ever is. That is what makes it so easy.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_10_confront.2"] = { en = "Take it from them and the Watch empties tonight. Not in a year. Tonight.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_10_confront.20"] = { en = "Then you have agreed with me and come anyway. How very much like the order.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_10_confront.21"] = { en = "...There it is.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_10_confront.22"] = { en = "...", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_10_confront.23"] = { en = "Yes.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_10_confront.24"] = { en = "All right.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_10_confront.25"] = { en = "Come and stand over here, child. You have been on that road a very long time.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_10_confront.3"] = { en = "I have done more for that line as a lie than I ever did with a shield in my hands. Put your weapon down and think about it honestly, which is more than the order ever managed.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_10_confront.4"] = { en = "...You're right.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_10_confront.5"] = { en = "Yes.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_10_confront.6"] = { en = "I have thought about it every mile of that road and I cannot answer you. Perhaps it does empty. Perhaps I am about to cost the line more than you ever did.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_10_confront.7"] = { en = "But you never chose that post. It was issued to you. And when it came due you set it down.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_10_confront.8"] = { en = "You. Girl. You have someone standing at your back.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_10_confront.9"] = { en = "Look at them properly. No post is worth holding. That includes theirs.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_10_intro.1"] = { en = "Past the gate that was opened from within.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_10_intro.2"] = { en = "Sworn. The order does not require this of you.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_10_intro.3"] = { en = "No. It wouldn't.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_10_intro.4"] = { en = "{name}. Whatever she says to me in there, I have already said it to myself. Every mile of the road here. Don't worry about me.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_10_intro.5"] = { en = "...Worry a little. But keep it to yourself.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_10_outro.1"] = { en = "She was smaller than the shield made her.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_10_outro.10"] = { en = "I have been trying to find a way to say this that is fair to you and I do not think there is one, so I am going to say it badly.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_10_outro.11"] = { en = "I watched you decide, over and over, and every time I told myself it was the road and not the person.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_10_outro.12"] = { en = "She said no post is worth holding. You did not argue with her. You have not argued with her for a long time.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_10_outro.13"] = { en = "...", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_10_outro.14"] = { en = "\"Rowan. Stay.\"", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_10_outro.15"] = { en = "\"...\"", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_10_outro.16"] = { en = "I know. I believe you mean it.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_10_outro.17"] = { en = "I swore to you in the ash and I meant that too, and I am still going to be somewhere the day it costs something.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_10_outro.18"] = { en = "It is not going to be here.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_10_outro.19"] = { en = "Do not follow me down that road. I will not stop.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_10_outro.2"] = { en = "They will read her name at muster tomorrow. Nobody there will know. I am not going to be the one who tells them. Not this month.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_10_outro.20"] = { en = "{name}. Come here. Sit down for a minute.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_10_outro.21"] = { en = "I have not felt like this since I was sixteen years old.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_10_outro.22"] = { en = "Fifteen years I have been carrying a full waterskin around asking people if they needed it, and nobody ever did, and I never once put it down.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_10_outro.23"] = { en = "You put it down for me. You did it so gently I did not notice you doing it.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_10_outro.24"] = { en = "The pike is hers. I am going to carry it. It is a good weapon and she has no further use for it.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_10_outro.25"] = { en = "...", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_10_outro.26"] = { en = "\"You've earned it.\"", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_10_outro.27"] = { en = "\"...\"", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_10_outro.28"] = { en = "There is nothing waiting for me at the muster tent and there never was.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_10_outro.29"] = { en = "Wherever you are going next, I am coming. Not because I swore anything.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_10_outro.3"] = { en = "Maybe the line empties. She may have been right about that. I will find out with everybody else.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_10_outro.30"] = { en = "Because I have got nothing else to do, and you are the only thing I like.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_10_outro.4"] = { en = "{name}.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_10_outro.5"] = { en = "Fifteen years the order taught me to hold until relieved. I never once noticed what that means. You wait for somebody else to decide you may stop.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_10_outro.6"] = { en = "I am not waiting to be relieved. I am not the relief either. I tried that, and it only meant running everywhere and arriving nowhere.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_10_outro.7"] = { en = "I am here, and it is you, and I picked it.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_10_outro.8"] = { en = "We shall hold.", ja = "" },  -- TODO
    ["line.conversation_bastion_slot_10_outro.9"] = { en = "{name}.", ja = "" },  -- TODO
    ["line.conversation_bastion_vendor_intro.1"] = { en = "The Watch outfits those who hold. Shields that outlast the arm behind them. Mail a knight can be found standing in. We do not arm those who run. State your post, or your reason for having none.", ja = "" },  -- TODO
    ["line.conversation_bastion_vendor_intro.2"] = { en = "I hold what's mine. That's post enough.", ja = "" },  -- TODO
    ["line.conversation_bastion_vendor_intro.3"] = { en = "I held a post on this order's line before I ever held a sword for {name}. Greywatch. The quartermaster knows the face, if not the years on it.", ja = "" },  -- TODO
    ["line.conversation_bastion_vendor_intro.4"] = { en = "Squire Rowan. Greywatch's own. It is an honor to arm you again.", ja = "" },  -- TODO
    ["line.conversation_bastion_vendor_intro.5"] = { en = "It is Rowan of no post now. I kept the oath and gave up the wall. I hold something better than a line these days. Outfit us both.", ja = "" },  -- TODO
    ["line.conversation_bastion_vendor_intro.6"] = { en = "Hold until relieved, then. The shelf is yours. The order remembers the ones who stay.", ja = "" },  -- TODO
    ["line.conversation_cafe_vendor_intro.1"] = { en = "You'll want feeding before you go. One order, {name}, and one is the whole of it. I'll not send a company up the hill on two breakfasts and a stomachache.", ja = "" },  -- TODO
    ["line.conversation_cafe_vendor_intro.2"] = { en = "One meal does that much?", ja = "" },  -- TODO
    ["line.conversation_cafe_vendor_intro.3"] = { en = "Mine does. Every one of yours eats it and every one of them carries it until the work is done. Read the board before you order. What's good for a long walk isn't what's good for a bad afternoon.", ja = "" },  -- TODO
    ["line.conversation_cathedral_discipline_unlocked.1"] = { en = "The {discipline}'s calling is open to you, {name}. What the Cathedral kept back for that path is on the shelf. Take what serves.", ja = "" },  -- TODO
    ["line.conversation_cathedral_discipline_unlocked.2"] = { en = "Then it's earned. Show me.", ja = "" },  -- TODO
    ["line.conversation_cathedral_discipline_unlocked.3"] = { en = "The Light gives what is earned, and you earned this. Carry it gently.", ja = "" },  -- TODO
    ["line.conversation_cathedral_slot_02_confront.1"] = { en = "Far enough. Stand off the cart and nobody on it gets a scratch.", ja = "" },  -- TODO
    ["line.conversation_cathedral_slot_02_confront.2"] = { en = "We only want the ones who can stand up. The house is short a card and the road is full.", ja = "" },  -- TODO
    ["line.conversation_cathedral_slot_02_confront.3"] = { en = "This cart is the Cathedral's. These people came to it on their own feet.", ja = "" },  -- TODO
    ["line.conversation_cathedral_slot_02_confront.4"] = { en = "So did ours, sister. We work the same mile you do and we get here first some nights.", ja = "" },  -- TODO
    ["line.conversation_cathedral_slot_02_confront.5"] = { en = "Nobody hands you a wagon and a blessing for it, that is the only difference I can find.", ja = "" },  -- TODO
    ["line.conversation_cathedral_slot_02_confront.6"] = { en = "Then find a better one. Nothing on this road is yours to take.", ja = "" },  -- TODO
    ["line.conversation_cathedral_slot_02_confront.7"] = { en = "Nets down. Now.", ja = "" },  -- TODO
    ["line.conversation_cathedral_slot_02_confront.8"] = { en = "Take them alive if you can, lads. Dead ones fill nothing.", ja = "" },  -- TODO
    ["line.conversation_cathedral_slot_04_outro.1"] = { en = "The fold is clear. That is what the Cathedral hired us for.", ja = "" },  -- TODO
    ["line.conversation_cathedral_slot_04_outro.10"] = { en = "I stood close enough to be certain. Three things happen at that altar.", ja = "" },  -- TODO
    ["line.conversation_cathedral_slot_04_outro.11"] = { en = "It takes, and you get a soldier who will die gladly and never know what is in him. It takes wrong, and you get a thing that is hunted afterwards, and called a demon out of the wild.", ja = "" },  -- TODO
    ["line.conversation_cathedral_slot_04_outro.12"] = { en = "Those. On the ground. In front of you. Every one of them was a child in that hall a season ago.", ja = "" },  -- TODO
    ["line.conversation_cathedral_slot_04_outro.13"] = { en = "I have put down three of those this year and been thanked for it.", ja = "" },  -- TODO
    ["line.conversation_cathedral_slot_04_outro.14"] = { en = "And it kills. Most often, it simply kills. The body goes out the back and into the pit I showed you, and the register writes the child down as ascended to the Light.", ja = "" },  -- TODO
    ["line.conversation_cathedral_slot_04_outro.15"] = { en = "The roll of our glorious dead is a casualty list. Everyone reads it aloud on the feast day. Nobody has ever once counted it.", ja = "" },  -- TODO
    ["line.conversation_cathedral_slot_04_outro.16"] = { en = "You knew this on the night you raised us. You held it a month.", ja = "" },  -- TODO
    ["line.conversation_cathedral_slot_04_outro.17"] = { en = "I held it until you could see it. Words would not have done this, and I would not have been believed.", ja = "" },  -- TODO
    ["line.conversation_cathedral_slot_04_outro.18"] = { en = "You are believed. Go on.", ja = "" },  -- TODO
    ["line.conversation_cathedral_slot_04_outro.19"] = { en = "How old are they when they take them?", ja = "" },  -- TODO
    ["line.conversation_cathedral_slot_04_outro.2"] = { en = "Do not put your sword away yet. Look at them first. Properly, all of them.", ja = "" },  -- TODO
    ["line.conversation_cathedral_slot_04_outro.20"] = { en = "Six. Seven. Young enough not to remember being asked, because they were not.", ja = "" },  -- TODO
    ["line.conversation_cathedral_slot_04_outro.21"] = { en = "Mm. Then I know the shape of your house, priest, and I have never set foot in it.", ja = "" },  -- TODO
    ["line.conversation_cathedral_slot_04_outro.22"] = { en = "I hid nine of them, before any of you knew me. I would have hidden ninety. That is the whole of my crime and I will not pretend to regret it in front of you.", ja = "" },  -- TODO
    ["line.conversation_cathedral_slot_04_outro.23"] = { en = "Then why has nobody in that building said a word?", ja = "" },  -- TODO
    ["line.conversation_cathedral_slot_04_outro.24"] = { en = "Because almost nobody in that building knows. That is what I need you to understand, and it is the part that sounds like an excuse.", ja = "" },  -- TODO
    ["line.conversation_cathedral_slot_04_outro.25"] = { en = "The faith is real. The people in it are good. I have knelt beside them my whole life. It is a small circle around the rite, and they have kept it from the rest of us for a generation.", ja = "" },  -- TODO
    ["line.conversation_cathedral_slot_04_outro.26"] = { en = "If the Saint herself were told, plainly, with proof she could not put aside. It would end that afternoon. I believe that. I have to; it is the last thing I have that is not on fire.", ja = "" },  -- TODO
    ["line.conversation_cathedral_slot_04_outro.27"] = { en = "That is a great deal of weight on one woman's ignorance.", ja = "" },  -- TODO
    ["line.conversation_cathedral_slot_04_outro.28"] = { en = "Yes. It is.", ja = "" },  -- TODO
    ["line.conversation_cathedral_slot_04_outro.29"] = { en = "A rite that kills most of the ones it is done to is not a rite. It is a yield. Somebody is running it as a yield.", ja = "" },  -- TODO
    ["line.conversation_cathedral_slot_04_outro.3"] = { en = "They are small.", ja = "" },  -- TODO
    ["line.conversation_cathedral_slot_04_outro.30"] = { en = "...I have not let myself put it that way.", ja = "" },  -- TODO
    ["line.conversation_cathedral_slot_04_outro.31"] = { en = "Somebody keeps that register. Ledgers don't write themselves, and the hand that keeps one always knows what it's for.", ja = "" },  -- TODO
    ["line.conversation_cathedral_slot_04_outro.32"] = { en = "Then we go and read it ourselves.", ja = "" },  -- TODO
    ["line.conversation_cathedral_slot_04_outro.33"] = { en = "You will not be let near it, and I cannot walk back in to fetch it. I am fallen, and the word is theirs to give, and they gave it the day I did not come home.", ja = "" },  -- TODO
    ["line.conversation_cathedral_slot_04_outro.34"] = { en = "But you were never the faith's hand. You were hired by it and you are still standing here counting bodies, which makes you the only outfit in this country I could have said any of this to.", ja = "" },  -- TODO
    ["line.conversation_cathedral_slot_04_outro.35"] = { en = "Take me to that room. I only want to be standing somewhere the truth can still be carried.", ja = "" },  -- TODO
    ["line.conversation_cathedral_slot_04_outro.4"] = { en = "Yes.", ja = "" },  -- TODO
    ["line.conversation_cathedral_slot_04_outro.5"] = { en = "I have been carrying this since the night I brought you back, and I told you there were older names in the book. Sit down. I will give you the rest of it.", ja = "" },  -- TODO
    ["line.conversation_cathedral_slot_04_outro.6"] = { en = "The children the faith takes in are sorted. Most are made anointed. The holy warriors you have cheered in the street. A few of us are kept back as clergy, and never blooded.", ja = "" },  -- TODO
    ["line.conversation_cathedral_slot_04_outro.7"] = { en = "Blooded. That is the word for it. There is a rite, and the rite puts something into a child, and what it puts in is not the Light.", ja = "" },  -- TODO
    ["line.conversation_cathedral_slot_04_outro.8"] = { en = "It is demon's blood.", ja = "" },  -- TODO
    ["line.conversation_cathedral_slot_04_outro.9"] = { en = "...You are certain.", ja = "" },  -- TODO
    ["line.conversation_cathedral_slot_10_confront.1"] = { en = "The little witness. Come back in their colors, a blade at your back. You saw the pits and could not look away, and here you are anyway. I never once feared you would come.", ja = "" },  -- TODO
    ["line.conversation_cathedral_slot_10_confront.2"] = { en = "I can take the blade. I can take every soul in these colors. But not you. There was never any of me put in you to call.", ja = "" },  -- TODO
    ["line.conversation_cathedral_slot_10_confront.3"] = { en = "You were the one we kept clean. No blooding, no leash. I used to think that a waste. Today I find it a mercy I can still spend.", ja = "" },  -- TODO
    ["line.conversation_cathedral_slot_10_confront.4"] = { en = "So let me give, for once. The one thing this house took from you and never gave back.", ja = "" },  -- TODO
    ["line.conversation_cathedral_slot_10_confront.5"] = { en = "I keep every name that was traded for the cloth. Yours among them: the child you were, before they wrote a virtue over her and worked her to the bone inside it. Kneel, and it is yours again.", ja = "" },  -- TODO
    ["line.conversation_cathedral_slot_10_confront.6"] = { en = "...", ja = "" },  -- TODO
    ["line.conversation_cathedral_slot_10_confront.7"] = { en = "That name is not yours to give. Taking it back from your hand would only be one more theft.", ja = "" },  -- TODO
    ["line.conversation_cathedral_slot_10_confront.8"] = { en = "I know what I am called. I gave it to myself. And that, I am keeping.", ja = "" },  -- TODO
    ["line.conversation_cathedral_vendor_intro.1"] = { en = "You come armed and you come clean. The faithful arm those who purge. Wards, relics, water that burns what should not walk. Kneel when you take them, and the taking is made holy.", ja = "" },  -- TODO
    ["line.conversation_cathedral_vendor_intro.2"] = { en = "I'll take them standing.", ja = "" },  -- TODO
    ["line.conversation_cathedral_vendor_intro.3"] = { en = "Give what is offered and no more, quartermaster. {name} came for a censer, not a catechism.", ja = "" },  -- TODO
    ["line.conversation_cathedral_vendor_intro.4"] = { en = "Sister. The cloth suits you still, whatever you tell the road.", ja = "" },  -- TODO
    ["line.conversation_cathedral_vendor_intro.5"] = { en = "It was never offered to me either. It was put on me. I wear what I choose to now. Arm us, and keep the sermon.", ja = "" },  -- TODO
    ["line.conversation_cathedral_vendor_intro.6"] = { en = "...As you will. The shelf is open. The faith asks only that its gifts be used as it intended them, and it always knows when they are not.", ja = "" },  -- TODO
    ["line.conversation_colosseum_discipline_unlocked.1"] = { en = "The {discipline}'s work is on your card now, {name}. The stable stocks for the fighters who reach it, and you reached it. Spend, and spend well.", ja = "" },  -- TODO
    ["line.conversation_colosseum_discipline_unlocked.2"] = { en = "Then it's earned. Show me.", ja = "" },  -- TODO
    ["line.conversation_colosseum_discipline_unlocked.3"] = { en = "Knew you had it in you. That gear's sharper than the house lets most touch. Go on, kit up.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_01_confront.1"] = { en = "Opening bout! On the sand. Nobody, no house, no record.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_01_confront.2"] = { en = "And against them, on hire from no one in particular: Saber.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_01_confront.3"] = { en = "On hire from whoever paid, thank you. It's a living.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_01_confront.4"] = { en = "Right. You've not done this before, so. Two things, free, because I'd rather it was a bout than a mess.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_01_confront.5"] = { en = "One. The crowd is not on your side and it is not against you. It does not know you exist yet. Stop listening to it.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_01_confront.6"] = { en = "Two.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_01_confront.7"] = { en = "Everyone your size opens careful. Feels each other out, three or four exchanges, learns the range.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_01_confront.8"] = { en = "I don't.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_01_event.1"] = { en = "The tunnel to the sand is that way. And a man in a very good coat has been watching you since the gate.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_01_event.2"] = { en = "House colors, no house name. A booking man, here to price the nobody before the crowd does. Choose...", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_01_event.3"] = { en = "Hear his offer.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_01_event.4"] = { en = "Walk past him to the sand.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_01_event.5"] = { en = "...forty in coin to open the card, win or lose, so long as the show is good. He's already written the ending. I take the money anyway.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_01_event.6"] = { en = "No handler, no leash, no debt at the door. Whatever happens on that sand is ours alone, and we walk to it steady.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_01_event.7"] = { en = "They put their opener up against a team with nothing behind it, and look at her: a mismatch in her favor and she's glad of it. Not hungry, not bored, just happy for the fight. No one's read her opening in years. Go be the first.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_01_intro.1"] = { en = "So. Fresh blood for the sand. The crowd does love a debut. Win or die.", ja = "ほう、砂場に新しい血か。観衆はデビュー戦が大好きだ――勝つか、死ぬかだ。" },
    ["line.conversation_colosseum_slot_01_intro.2"] = { en = "We came to fight, not to be entertainment.", ja = "戦いに来た。見世物になりに来たわけじゃない。" },
    ["line.conversation_colosseum_slot_01_intro.3"] = { en = "Here they are the same thing. Tell me. Why should the arena remember your name?", ja = "ここでは同じことさ。言ってみろ――なぜ闘技場がお前の名を覚えるべきなのか?" },
    ["line.conversation_colosseum_slot_01_intro.4"] = { en = "\"Because we fight for coin.\"", ja = "「金のために戦うからだ。」" },
    ["line.conversation_colosseum_slot_01_intro.5"] = { en = "\"Because we fight for honor.\"", ja = "「誇りのために戦うからだ。」" },
    ["line.conversation_colosseum_slot_01_intro.6"] = { en = "Honest, at least. The purse is yours if you live.", ja = "少なくとも正直だな。生き延びれば賞金はお前のものだ。" },
    ["line.conversation_colosseum_slot_01_intro.7"] = { en = "Honor. The crowd will cheer it and forget it by morning.", ja = "誇りか。観衆は歓声を上げ、朝には忘れるだろう。" },
    ["line.conversation_colosseum_slot_01_intro.8"] = { en = "Then let us be quick about it. The Light is watching, even here.", ja = "では手短に済ませよう。光はここでも見ておられる。" },
    ["line.conversation_colosseum_slot_01_intro.9"] = { en = "Watching, and unimpressed. Open the gate.", ja = "見ていて、しかも呆れているがな。門を開けろ。" },
    ["line.conversation_colosseum_slot_01_join.1"] = { en = "Footsteps behind us. The same weight that put me on my back an hour ago. She followed us out.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_01_join.2"] = { en = "Easy, knight. If I meant you harm I'd not announce it with my boots.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_01_join.3"] = { en = "Saber. That's the name the card gives me, and it'll do. You'll have heard the house one shouted over the sand. Forget that one. It was rented.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_01_join.4"] = { en = "I open every bout the same way, and no one has read it in years. You two did, and I had more fun losing that than I've had winning since I can remember. You didn't flinch at the crowd, you didn't flinch at me, and nobody paid you to stand there.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_01_join.5"] = { en = "{name}. No house, no handler, no leash at the gate. Someone will tell you that's a weakness before the week's out. It isn't. On that sand it is the only thing worth owning.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_01_join.6"] = { en = "There is a reckoning owed under this arena. Its patron has eaten better fighters than me, one at a time, because one at a time is how she likes them. I cannot reach her alone. You are the first outfit I've met that might.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_01_join.7"] = { en = "So. No coin this round, no booking, no ending written for me before the bell. Just the first fight in years I'd follow off the sand. I'm asking straight: take me on.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_01_join.8"] = { en = "You unseated a sworn knight in front of a house that wanted you to win, veteran. I would far rather have that swinging beside us than waiting on the next card.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_01_join.9"] = { en = "Then it's a team, and it has nothing behind it, and I have wanted that for longer than I'd say. Lead on. Let's see how far it goes.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_01_kit.1"] = { en = "Someone kitted up for this card and never made it to the sand. Their bag's still here, straps cut in a hurry.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_01_kit.2"] = { en = "Cleansing draughts. A couple of clearwater vials and a panacea besides. Choose...", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_01_kit.3"] = { en = "Take the lot.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_01_kit.4"] = { en = "Rowan. Why would a fighter bring these to a sword bout?", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_01_kit.5"] = { en = "Because a house like the one we're drawn against doesn't win with the sword alone. It fields netters. They'll rope your legs and hold you still while the big blade winds up. Drink one the moment you're pinned and it cuts you loose. You get your step back before the swing lands. A panacea will do the same for whoever's caught beside you. Don't stand there roped, waiting for it.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_01_kit.6"] = { en = "Cut loose, then move. Understood. Let's not keep the veteran waiting.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_01_outro.1"] = { en = "Enough. Enough! It's been years since anyone put me on my back on this sand.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_01_outro.2"] = { en = "I've watched this place feed fighters to its patron, one after another. I will not be fed. And you two. No house behind you, and you still put me down.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_01_outro.3"] = { en = "Well fought. The Adventurers' Guild is always short of people who live through their first bout.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_01_outro.4"] = { en = "You want the Demon Lord? So does everyone who's lost a home. But it is only strong because of its seven. Its generals, its appetites. Unmake them one by one, and the crown is hollow. The board is open to you. Start climbing.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_01_outro.5"] = { en = "Walk out slow. I'll catch you past the gate. There's a thing I mean to ask, and not with a booking man breathing on it.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_02_intro.1"] = { en = "BEAT: the promoter frames tonight's opener as a warm-up, and lets slip what the crowd is really here to see: the road's newest arrivals put down.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_02_intro.2"] = { en = "BEAT: the avatar reads the far side of the sand. These people were not brought here to fight; they are refugees, off the same road we came in on.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_02_intro.3"] = { en = "BEAT: Rowan recognizes the village elder among them. One of the people they carried out of the fire in the prologue. Swept off the bread line and onto the sand.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_02_intro.4"] = { en = "BEAT: the crowd hates them and paid to watch them bleed; the house only prints what sells, and the card is already set.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_02_intro.5"] = { en = "BEAT: Saber already knows what this is. She has watched promoters run it for years, and does not look away.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_02_intro.6"] = { en = "BEAT: she is going down onto the sand first. Between the killers and the refugees. Before anyone asks her to; everyone gets to walk off it.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_02_intro.7"] = { en = "BEAT: the choice lands on the player. Hold the line for these people, or let the house have its slaughter.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_02_join.1"] = { en = "This is not the arena. Where am I?", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_02_join.10"] = { en = "Of course they did. A dead draw earns nobody anything.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_02_join.11"] = { en = "Hear it plainly, {name}. We are owned by four men we have never met until we win it back.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_02_join.12"] = { en = "What about the people on the sand with us?", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_02_join.13"] = { en = "...They came in on the same cart. Every one of them.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_02_join.14"] = { en = "No one paid for them.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_02_join.15"] = { en = "There was an elder among them. Grey, small, a burn across one hand. Tell me where they are.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_02_join.16"] = { en = "I can tell you exactly where. I carried them there myself.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_02_join.17"] = { en = "There is a book in this house. Every soul the Cathedral receives goes into it, and I am one of the hands that writes it.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_02_join.18"] = { en = "I wrote every one of them in this morning. Ascended to the Light. That is the wording. It is the only wording there is.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_02_join.19"] = { en = "Then I took them out the back to the pit behind the almshouse, and there is no marker on it, and there never has been.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_02_join.2"] = { en = "Lie still a moment. You have been dead since the third bell.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_02_join.20"] = { en = "Ascended. They were butchered on a sand floor for a crowd.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_02_join.21"] = { en = "I know what they were. I am the only one in this building who does.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_02_join.22"] = { en = "That book has other names in it. Older ones. I will not talk about those tonight and I am asking you not to make me.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_02_join.23"] = { en = "Then talk about them.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_02_join.24"] = { en = "There is nobody left to. Everyone who stood on that sand and saw it is in the pit, and you are lying in front of me.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_02_join.25"] = { en = "You are the last people alive who know what actually happened out there. By the feast day this house will have read those names aloud as saints and meant it.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_02_join.27"] = { en = "So I am not staying here. Take me with you.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_02_join.28"] = { en = "You just gave us our lives back. Why ask?", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_02_join.29"] = { en = "Because a thing given is not a thing owed. You are free of me the moment you stand up.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_02_join.3"] = { en = "Dead.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_02_join.30"] = { en = "I want to be standing somewhere the truth can still be carried, and there is one outfit in this city that is not the house or the faith or the stables. It is you.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_02_join.31"] = { en = "I will not ask you for a wage, or a share, or a say in where we go. I have never been much good at wanting things for myself. They were thorough about that.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_02_join.32"] = { en = "You can want a wage too. We will start there.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_02_join.33"] = { en = "...I will think about it.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_02_join.34"] = { en = "Then get your boots, priest. And keep close to me on the road.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_02_join.35"] = { en = "My order does the same with its own dead. We carve a mark for each of them and teach the children the marks are days held.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_02_join.4"] = { en = "All of you. They brought you in on the cart with the rest. I have had my hands on your heart for an hour.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_02_join.5"] = { en = "I remember the sand. I remember standing in front of you and then nothing at all.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_02_join.6"] = { en = "This is the Cathedral. I am Amana. I am an acolyte here, and the rite that brought you back is the most expensive thing this house owns.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_02_join.7"] = { en = "We have no money for that.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_02_join.8"] = { en = "You did not pay for it. Four stables did, before your bodies were cold.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_02_join.9"] = { en = "They watched you fight twice and they had coin on you, and the house they book with destroyed you in front of them. So they bought you back to fight again.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_02_overrule.1"] = { en = "The killers are down. Every one of these people is still standing.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_02_overrule.10"] = { en = "Everyone walks off the sand. That is the one law this place has ever kept.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_02_overrule.11"] = { en = "She is going for them. Get in front of them, all of you!", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_02_overrule.2"] = { en = "The elder is up, {name}. We have carried that one out of two fires now.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_02_overrule.3"] = { en = "Well fought. The house has no complaint with you.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_02_overrule.4"] = { en = "The crowd paid for a night, though. The house always gives them the night.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_02_overrule.5"] = { en = "Open the far gate.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_02_overrule.6"] = { en = "Who is that?", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_02_overrule.7"] = { en = "That is the patron of this house. Put your sword down, {name}.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_02_overrule.8"] = { en = "She is not an opponent. Nobody cards her against anyone.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_02_overrule.9"] = { en = "Her own hand, and on an opener. You will not see that twice in a life.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_03_intro.1"] = { en = "BEAT: the vendor gives the job. The Warlord fought under our banner once; bring him back, or bring him down.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_03_intro.2"] = { en = "BEAT: the avatar clocks that this one is a genuine bout, a named fighter on the other side, not a culling.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_03_intro.3"] = { en = "BEAT: Saber is alight. THIS is the thing she loves: house against a fighter with a name, honest, no padding.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_03_outro.1"] = { en = "BEAT: the avatar marks it. That was a real bout, the best kind, fought clean.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_03_outro.2"] = { en = "BEAT: Saber is happier than the player has seen her. The craft, the read, the moment; this is the whole reason she never left the sand.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_03_outro.3"] = { en = "BEAT: a beat of pure, unguarded trust in the sport. She has no idea yet what the arena she loves is built on, and the player is about to.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_04_intro.1"] = { en = "BEAT: the vendor puts the reigning house's four on the card. The stable that wins, and has for longer than anyone finds strange.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_04_intro.2"] = { en = "BEAT: the avatar sizes them up. Watch how they fight; watch how they do not celebrate.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_04_intro.3"] = { en = "BEAT: Saber goes quiet the moment she sees them. She reads the house style cold, but it is HOW they move that unsettles her: like people not allowed to want anything. She will not name it yet.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_04_outro.1"] = { en = "BEAT: the avatar notes it aloud. They fought identically, none flinched, none celebrated.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_04_outro.2"] = { en = "BEAT: Saber called all four openings before they came; the player asks how she knew.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_04_outro.3"] = { en = "BEAT: she deflects. Circling something she is not ready to say, and the not-answering is louder than an answer.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_05_intro.1"] = { en = "BEAT: the vendor points them at the intake hall. Get in and read the ledger; the stewards are in the way.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_05_intro.2"] = { en = "BEAT: the avatar registers what the ledger actually records. Children received by year, wins on the facing page, kept with pride.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_05_intro.3"] = { en = "BEAT: Saber has gone very still. She has worked out what this ledger is before they reach it, and says nothing on the way in.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_05_outro.1"] = { en = "BEAT: Saber reads the facing pages aloud. Children in one column, wins in the other, and names it flat: this is not an academy, it is a stockyard. They are bought, not schooled; kept, not trained.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_05_outro.2"] = { en = "BEAT: the thing she read in the roster, said at last. Those fighters move like people who are not allowed to leave, because they are not; the sport was never the wrong thing, but this is. She asks for nothing.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_05_outro.3"] = { en = "BEAT: the avatar lets it stand. Does not push, having just understood what the whole line was circling: the patron under the sand is what this ledger makes.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_06_intro.1"] = { en = "BEAT: the promoter is warm, generous. Your name is the gate now, so we have taken care of your undercard for you.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_06_intro.2"] = { en = "BEAT: the avatar realises the padding is the same thing as slot 2, only this time it is being done FOR them, and nobody thought to ask.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_06_intro.3"] = { en = "BEAT: Saber says nothing yet, but the mirror lands on both of them: the house that isn't one has started behaving like the others because they are winning.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_06_outro.1"] = { en = "BEAT: Saber asks it straight. Do you mean to keep taking the top billing?, and makes clear she wants a real answer, not a shrug.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_06_outro.2"] = { en = "BEAT: the choice is the player's, and the scene leaves it standing rather than resolving it. The billing is how they get to Ira at all.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_07_confront.1"] = { en = "BEAT: Ira reads them by weight on the sand; notes this bout is on the schedule like any other, and it ends at the bell whatever happens.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_07_confront.2"] = { en = "BEAT: the avatar tries to speak TO her. To reach the person, to find a grievance or a name, some way to get her out of this.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_07_confront.3"] = { en = "BEAT: she gives them nothing to bargain with, not cruelty, there is simply no door to offer her; the house lets her win or kill, and there was never a third thing.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_07_confront.4"] = { en = "BEAT: Saber tries once, in the plainest terms she has, to reach her. Offers to get her out, somewhere else to be.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_07_confront.5"] = { en = "BEAT: Ira closes the door, gently and completely. She already found the only other door, and it shut behind her; there is nowhere left to put her. Saber hears it land. (Hold the finale's biggest lines back.)", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_07_intro.1"] = { en = "BEAT: the house books them onto the patron's card. You are not expected to win; stay standing until the bell.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_07_intro.2"] = { en = "BEAT: the avatar asks what she actually IS, since nobody in the building will say it plainly.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_07_intro.3"] = { en = "BEAT: Saber warns the player how the fight goes. Do not trade with her; every blow you land only wakes her, and she is sure because she has watched the patron eat challengers who tried to grind her down.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_07_outro.1"] = { en = "BEAT: the avatar, still standing at the bell, takes in what just happened. There was no one to reach.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_07_outro.2"] = { en = "BEAT: Saber says the quiet thing. She came in believing there was somewhere else Ira could be put, and there is not.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_07_outro.3"] = { en = "BEAT: the hope goes out of her; from here she is not hoping to save Ira, she is deciding what she owes her.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_08_intro.1"] = { en = "BEAT: Saber stops waiting. In front of people, she asks the house for the match with Ira and names the day, out loud.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_08_intro.2"] = { en = "BEAT: the house cannot say yes and cannot say what Ira is, so it answers the only way it has. It matches her, against the fighter it keeps for people who ask questions in public.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_08_intro.3"] = { en = "BEAT: the avatar registers that a question just got answered with a bout, and that Saber chose this moment on purpose.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_08_outro.1"] = { en = "BEAT: the avatar names what changed. For seven quests she waited; tonight she picked the moment, and that is not the same thing.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_08_outro.2"] = { en = "BEAT: Saber owns the distinction. Waiting was never the virtue; choosing when to commit is; and she has decided to commit.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_08_outro.3"] = { en = "BEAT: the second-relic beat. She takes / is handed the thing that lets her choose her one moment outright, instead of leaving it to the odds. (Owes Saber's 2nd relic item.)", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_09_intro.1"] = { en = "BEAT: the house, cornered, has scheduled its own trainers onto a disposal card. Framed as ordinary sport, so by morning there is nothing left to ask about.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_09_intro.2"] = { en = "BEAT: the avatar clocks the move. The house will spend anyone, including its own architects, before it says one true sentence; the player is the only one trying to stop it.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_09_intro.3"] = { en = "BEAT: Saber goes because it is the same crime one more time. The house feeding the sand people who never chose to be there, and she will not let it be a show. The last quiet before the sand.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_09_outro.1"] = { en = "BEAT: the avatar says the hard thing plainly. Killing Ira ends Ira, and nothing else; the Perennial trains again within a year.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_09_outro.2"] = { en = "BEAT: Saber does not argue it. She knows, and reframes what they are actually going down there to do, and for whom.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_09_outro.3"] = { en = "BEAT: the last quiet before slot 10. She is done deferring and done hoping; what is left is what she owes Ira.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_10_confront.1"] = { en = "BEAT: she reads that they arrive already wounded (one favours a foot). They fought their way to her; everything that reaches her is a card.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_10_confront.11"] = { en = "BEAT: she will tell them what she is, because they will not otherwise believe it of a person.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_10_confront.12"] = { en = "BEAT: made by the Perennial to win. Owned since before she can remember, drilled before she could choose anything at all.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_10_confront.13"] = { en = "BEAT: she was superb, and none of it was hers. Never once chose a fight, an opponent, a morning.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_10_confront.14"] = { en = "BEAT: the one thing she ever wanted was to belong to herself; she held it down for years, sullen and hidden, and it was the engine of everything the crowd cheered.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_10_confront.15"] = { en = "BEAT: so she made the bargain herself. The Demon Lord promised freedom, and the strength to take it.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_10_confront.16"] = { en = "BEAT: Ren. 'and it gave you?'", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_10_confront.17"] = { en = "BEAT: strength, and a rage she cannot govern, not a way out but a deeper cage, one she now carries inside.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_10_confront.18"] = { en = "BEAT: Ren knows the shape of that bargain, and can barely say it.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_10_confront.19"] = { en = "BEAT: Clem, so there is no getting out now, no term to serve, no price that buys it back.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_10_confront.2"] = { en = "BEAT: the bout was set for the ninth; they moved it up and no one told her. She is told when she fights, never asked.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_10_confront.20"] = { en = "BEAT: no; she spent her freedom on the lock.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_10_confront.21"] = { en = "BEAT: Amana. How old were you when they took you.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_10_confront.22"] = { en = "BEAT: there was no before; no part of her predates the house.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_10_confront.23"] = { en = "BEAT: Amana knows a house that takes children; did not know there were two.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_10_confront.24"] = { en = "BEAT: Rowan, and the stable never once said what it had made.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_10_confront.25"] = { en = "BEAT: it cannot; saying what she is means saying its champions are owned, and the intake is still running. Children in it tonight.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_10_confront.26"] = { en = "BEAT: Gyeom. A fighter who is not allowed to stop is not a champion, it is a chained dog.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_10_confront.27"] = { en = "BEAT: yes; she has been told she is the finest chained dog in the world.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_10_confront.28"] = { en = "BEAT: Kaya. Everything in a wood can run, and the running is what keeps it alive; they built her with the leaving taken out.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_10_confront.29"] = { en = "BEAT: they took out the leaving, not the wanting. That was their mistake.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_10_confront.3"] = { en = "BEAT: the avatar catches on 'told, never asked'.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_10_confront.30"] = { en = "BEAT: she has heard Saber once put her sword down on a full house and would not finish a slaughter.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_10_confront.31"] = { en = "BEAT: Saber. They died anyway; someone else did it while she stood there.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_10_confront.32"] = { en = "BEAT: she thinks of that. A fighter who was allowed to choose to stop, on a sand where Ira never was.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_10_confront.34"] = { en = "BEAT: Saber. She came believing she could get Ira OUT; that there was somewhere else to put her, some other door.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_10_confront.35"] = { en = "BEAT: there is no other door; she bought the last one, and this is what was on the far side of it.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_10_confront.36"] = { en = "BEAT: 'I bought my way out. This is what was on the other side.'. The line the whole scene turns on.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_10_confront.37"] = { en = "BEAT: come and hit her PROPERLY, not fast; a fast blow is a blow held back, and she is done holding anything back.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_10_confront.38"] = { en = "BEAT: every blow wakes more of it; the nearer she is to gone, the less of her is left to hold it, and she will not hold it.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_10_confront.39"] = { en = "BEAT: the avatar. That is not a reason to keep going.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_10_confront.4"] = { en = "BEAT: every fight of her life was set for her by someone else; the sand was the only place she ever moved on her own accord, and that is exactly why she is good at it.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_10_confront.40"] = { en = "BEAT: it is the only thing left that is hers to spend, and she means to spend all of it; begin.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_10_confront.41"] = { en = "BEAT: Saber. 'Everyone gets to walk off the sand.' Ira never could.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_10_confront.42"] = { en = "BEAT: ...so she is going to carry her off it the only way that is left, and would rather no one call it mercy. Even though it is.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_10_confront.5"] = { en = "BEAT: she reads Saber. No house-weight on her, moves like she could walk off any moment.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_10_confront.6"] = { en = "BEAT: Saber names her.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_10_confront.7"] = { en = "BEAT: Saber fights because she wants to; Ira was never once allowed to want to.", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_10_confront.8"] = { en = "BEAT: Saber. 'I fight because I love it. You fight because it's the only door they ever left open.'", ja = "" },  -- TODO
    ["line.conversation_colosseum_slot_10_confront.9"] = { en = "BEAT: the only door, yes, and she went and found herself a second one, and it closed behind her.", ja = "" },  -- TODO
    ["line.conversation_colosseum_vendor_intro.1"] = { en = "You walked off the sand still breathing, so the shelf is yours. Steel, leathers, the little cruelties that keep a fighter on the card one more week. No house behind you? Good. A house takes a cut. I only take coin.", ja = "" },  -- TODO
    ["line.conversation_colosseum_vendor_intro.2"] = { en = "Then coin is all you'll get.", ja = "" },  -- TODO
    ["line.conversation_colosseum_vendor_intro.3"] = { en = "He says that to every fresh name, {name}. The cut comes later, dressed as a favour. I've worn three houses' colors and paid each one twice.", ja = "" },  -- TODO
    ["line.conversation_colosseum_vendor_intro.4"] = { en = "And yet here you stand, veteran, shilling for a team with nothing behind it.", ja = "" },  -- TODO
    ["line.conversation_colosseum_vendor_intro.5"] = { en = "Nothing behind it is the only thing on this sand I have ever trusted. Sell them the good leathers, not the ones you move on the losers.", ja = "" },  -- TODO
    ["line.conversation_colosseum_vendor_intro.6"] = { en = "...The good leathers, then. Win loud, {name}. The crowd keeps a name, and a name is the only thing here I can't sell you. You earn that one blow by blow.", ja = "" },  -- TODO
    ["line.conversation_flight_champion.1"] = { en = "Stop here, {name}. That one at the head of them is no imp. It has a name where they carry none, and it leads this whole raiding party. This is the thing that has been walking the road behind us.", ja = "" },  -- TODO
    ["line.conversation_flight_champion.2"] = { en = "It's between us and the capital.", ja = "" },  -- TODO
    ["line.conversation_flight_champion.3"] = { en = "It is. And it will not fall to the swarm-work that served against the rest. It takes blows the grunts could not, and the imps beside it only want to keep us busy while it reaches you.", ja = "" },  -- TODO
    ["line.conversation_flight_champion.4"] = { en = "Then we cut it down and the imps stop mattering.", ja = "" },  -- TODO
    ["line.conversation_flight_champion.5"] = { en = "Just so. Put it down and the road opens. Stay off its reach, let it come onto our line, and we end this at the gate rather than inside it. Ready when you are.", ja = "" },  -- TODO
    ["line.conversation_flight_event_shrine.1"] = { en = "A wayside shrine, still standing where everything around it burned.", ja = "" },  -- TODO
    ["line.conversation_flight_event_shrine.2"] = { en = "Someone tended it to the last, and cut a healer's rite into the stone. It feels wrong to walk straight past. Choose...", ja = "" },  -- TODO
    ["line.conversation_flight_event_shrine.3"] = { en = "Kneel and learn the rite by heart.", ja = "" },  -- TODO
    ["line.conversation_flight_event_shrine.4"] = { en = "Tend our wounds and press on.", ja = "" },  -- TODO
    ["line.conversation_flight_event_shrine.5"] = { en = "...there. It holds. I can set a wound to closing now, slow and sure. Even one that is not my own.", ja = "" },  -- TODO
    ["line.conversation_flight_event_shrine.6"] = { en = "Patched, and the worse for wear behind us. The rite we leave for whoever comes after. We've a road to make.", ja = "" },  -- TODO
    ["line.conversation_flight_event_shrine.7"] = { en = "The capital, then. Keep moving.", ja = "" },  -- TODO
    ["line.conversation_flight_event_survivor.1"] = { en = "Hold. Someone's in the brush. Hurt, and trying not to be heard.", ja = "" },  -- TODO
    ["line.conversation_flight_event_survivor.2"] = { en = "Easy. We're not with the things that did this. Choose...", ja = "" },  -- TODO
    ["line.conversation_flight_event_survivor.3"] = { en = "Ask which way the demons went.", ja = "" },  -- TODO
    ["line.conversation_flight_event_survivor.4"] = { en = "Share what little we carry, and press on.", ja = "" },  -- TODO
    ["line.conversation_flight_event_survivor.5"] = { en = "...north, along the ridge, in numbers. Good. We take the low road. And she gave you the tell: where a demon's guard runs thin, if you mark it before the strike.", ja = "" },  -- TODO
    ["line.conversation_flight_event_survivor.6"] = { en = "Nothing to spare but thanks, and she gave that freely. An assayer's lens, pressed on you in kind: look through it and a demon's satchel keeps nothing back.", ja = "" },  -- TODO
    ["line.conversation_flight_event_survivor.7"] = { en = "An apothecary, before the fires. Then the capital: reach the walls.", ja = "" },  -- TODO
    ["line.conversation_gate_below_confront.1"] = { en = "You came a long way down to meet me, and there is no me to meet.", ja = "" },  -- TODO
    ["line.conversation_gate_below_confront.10"] = { en = "I know. I stopped waiting. You are forty-one days too late to frighten me with it.", ja = "" },  -- TODO
    ["line.conversation_gate_below_confront.11"] = { en = "There is nothing in you I have not already surpassed.", ja = "" },  -- TODO
    ["line.conversation_gate_below_confront.12"] = { en = "You are reciting. She meant it. That was what was wrong with her. You are just holding the sound.", ja = "" },  -- TODO
    ["line.conversation_gate_below_confront.13"] = { en = "Kneel, and I will give you back the name they took.", ja = "" },  -- TODO
    ["line.conversation_gate_below_confront.14"] = { en = "I have a name. I gave it to myself, and you were not there.", ja = "" },  -- TODO
    ["line.conversation_gate_below_confront.15"] = { en = "The board never closes. There will be more in the spring. There are always more in the spring.", ja = "" },  -- TODO
    ["line.conversation_gate_below_confront.16"] = { en = "Then we will be there in the spring.", ja = "" },  -- TODO
    ["line.conversation_gate_below_confront.17"] = { en = "Everything made can be unmade cheaper. Ask the girl who was poured.", ja = "" },  -- TODO
    ["line.conversation_gate_below_confront.18"] = { en = "I did ask her. That is the difference between us, and it is not a small one.", ja = "" },  -- TODO
    ["line.conversation_gate_below_confront.19"] = { en = "Everything is owed. Everything comes back to the house in the end.", ja = "" },  -- TODO
    ["line.conversation_gate_below_confront.2"] = { en = "Seven appetites. That was the whole of it. Seven wants, and seven people who agreed to carry one each, because a want cannot walk about on its own.", ja = "" },  -- TODO
    ["line.conversation_gate_below_confront.20"] = { en = "Not this. This one I am writing off.", ja = "" },  -- TODO
    ["line.conversation_gate_below_confront.21"] = { en = "You see? I still have all of them. And I can put one back on whenever I care to.", ja = "" },  -- TODO
    ["line.conversation_gate_below_confront.22"] = { en = "So do it properly, if you are going to. Not the appetite this time.", ja = "" },  -- TODO
    ["line.conversation_gate_below_confront.23"] = { en = "The thing that was hungry.", ja = "" },  -- TODO
    ["line.conversation_gate_below_confront.24"] = { en = "That is what we came down for.", ja = "" },  -- TODO
    ["line.conversation_gate_below_confront.3"] = { en = "You took them off me one at a time. Careful work. I felt every one go the way you feel a tooth go, not pain. An absence, with an edge on it.", ja = "" },  -- TODO
    ["line.conversation_gate_below_confront.4"] = { en = "Then there is nothing left of you.", ja = "" },  -- TODO
    ["line.conversation_gate_below_confront.5"] = { en = "Nothing is not the same as harmless.", ja = "" },  -- TODO
    ["line.conversation_gate_below_confront.6"] = { en = "I kept nothing of their souls. Souls are not food, and I was never sentimental. What I keep is the SHAPE a person makes when they say yes.", ja = "" },  -- TODO
    ["line.conversation_gate_below_confront.7"] = { en = "Come and be measured, little card-filler. You were always going to lose to somebody the house had already paid.", ja = "" },  -- TODO
    ["line.conversation_gate_below_confront.8"] = { en = "That is her mouth and it is not her. She never once said a thing she had been paid to say. That was the whole trouble with her.", ja = "" },  -- TODO
    ["line.conversation_gate_below_confront.9"] = { en = "Hold until relieved. Nobody is coming, girl. Nobody was ever coming.", ja = "" },  -- TODO
    ["line.conversation_gate_below_ending.1"] = { en = "...", ja = "" },  -- TODO
    ["line.conversation_gate_below_ending.10"] = { en = "There is a reckoning owed under this floor and it is paid. I have wanted that since before I had a name that was mine to give out.", ja = "" },  -- TODO
    ["line.conversation_gate_below_ending.11"] = { en = "Nobody booked this one. Nobody wrote the ending. It came out how it came out, and it is ours.", ja = "" },  -- TODO
    ["line.conversation_gate_below_ending.12"] = { en = "Listen to it. That is the quietest a wood has been in my whole life, and I have spent my whole life making woods quiet.", ja = "" },  -- TODO
    ["line.conversation_gate_below_ending.13"] = { en = "I do not think I have to any more.", ja = "" },  -- TODO
    ["line.conversation_gate_below_ending.14"] = { en = "You are all standing. I want to say that out loud, because I spent the entire way down assuming I would be counting.", ja = "" },  -- TODO
    ["line.conversation_gate_below_ending.15"] = { en = "Somebody put a hand under me on the stair, and I let them. That is new. I am keeping it.", ja = "" },  -- TODO
    ["line.conversation_gate_below_ending.16"] = { en = "Everything is owed, it said. Everything comes back to the house.", ja = "" },  -- TODO
    ["line.conversation_gate_below_ending.17"] = { en = "The house is a hole in the ground and I am walking out of it. Let it stay owed.", ja = "" },  -- TODO
    ["line.conversation_gate_below_ending.18"] = { en = "...including mine. Fine. Especially mine.", ja = "" },  -- TODO
    ["line.conversation_gate_below_ending.19"] = { en = "Nobody up there is going to know what this was.", ja = "" },  -- TODO
    ["line.conversation_gate_below_ending.2"] = { en = "It is not leaving anything behind.", ja = "" },  -- TODO
    ["line.conversation_gate_below_ending.20"] = { en = "The board will post work in the morning. The shops will open. Somebody will complain about the price of steel.", ja = "" },  -- TODO
    ["line.conversation_gate_below_ending.21"] = { en = "That is the whole of what we were for. That it stays boring up there.", ja = "" },  -- TODO
    ["line.conversation_gate_below_ending.22"] = { en = "Come on. It is a long stair and I would like to see the sky do the thing it does.", ja = "" },  -- TODO
    ["line.conversation_gate_below_ending.23"] = { en = "It wore Rowan at three quarters. It did not even reach very far.", ja = "" },  -- TODO
    ["line.conversation_gate_below_ending.24"] = { en = "Saber went over without breaking stride. She had been ready for a while.", ja = "" },  -- TODO
    ["line.conversation_gate_below_ending.25"] = { en = "Amana asked me for nothing at the end. She just took it.", ja = "" },  -- TODO
    ["line.conversation_gate_below_ending.26"] = { en = "Kaya did not stop. I do not think she could have by then.", ja = "" },  -- TODO
    ["line.conversation_gate_below_ending.27"] = { en = "Gyeom had an answer ready for everything I did. She always had one. That was new.", ja = "" },  -- TODO
    ["line.conversation_gate_below_ending.28"] = { en = "Clem collected. After everything, at the very end, she collected.", ja = "" },  -- TODO
    ["line.conversation_gate_below_ending.29"] = { en = "Ren took a shape off me and wore it at me. She was so pleased with it.", ja = "" },  -- TODO
    ["line.conversation_gate_below_ending.3"] = { en = "No shape on the floor. No last word. It emptied out like a coat coming off a hook.", ja = "" },  -- TODO
    ["line.conversation_gate_below_ending.30"] = { en = "...", ja = "" },  -- TODO
    ["line.conversation_gate_below_ending.31"] = { en = "It emptied out like a coat coming off a hook. That is what I keep saying.", ja = "" },  -- TODO
    ["line.conversation_gate_below_ending.32"] = { en = "A hook is not a thing that is finished with. A hook is a thing that is waiting.", ja = "" },  -- TODO
    ["line.conversation_gate_below_ending.33"] = { en = "And I hung them on it myself, one at a time, and every single time I thought I was being kind.", ja = "" },  -- TODO
    ["line.conversation_gate_below_ending.4"] = { en = "Because that is what it was. We kept expecting a thing wearing seven appetites. It was seven appetites wearing a thing.", ja = "" },  -- TODO
    ["line.conversation_gate_below_ending.5"] = { en = "Take them off and you are not left with a monster. You are left with the hook.", ja = "" },  -- TODO
    ["line.conversation_gate_below_ending.6"] = { en = "Seven people said yes to it.", ja = "" },  -- TODO
    ["line.conversation_gate_below_ending.7"] = { en = "That part does not come off. We killed the wanting. We did not un-ask the question, and it was asked of them, and every one of them answered.", ja = "" },  -- TODO
    ["line.conversation_gate_below_ending.8"] = { en = "Forty-one of mine answered it too, and they were not monsters when they did. They were cold, and tired, and somebody offered.", ja = "" },  -- TODO
    ["line.conversation_gate_below_ending.9"] = { en = "I have stopped being able to tell that story as though the ending was obvious.", ja = "" },  -- TODO
    ["line.conversation_hunters_lodge_discipline_unlocked.1"] = { en = "You walk the {discipline}'s trail now, {name}. The Lodge sets out gear for the ones who get this far. It is yours to draw.", ja = "" },  -- TODO
    ["line.conversation_hunters_lodge_discipline_unlocked.2"] = { en = "Then it's earned. Show me.", ja = "" },  -- TODO
    ["line.conversation_hunters_lodge_discipline_unlocked.3"] = { en = "That path knows when to stop. Take the kit. Remember the lesson with it.", ja = "" },  -- TODO
    ["line.conversation_hunters_lodge_slot_02_confront.1"] = { en = "The bounty led us this deep. The trees closed behind us, and they are starving, all of them. Nothing out here is afraid of us.", ja = "" },  -- TODO
    ["line.conversation_hunters_lodge_slot_02_confront.2"] = { en = "Because something upwind is eating the whole wood, and it has not left them enough. Stand your ground. The wolf and I will turn the mad ones back. You only have to still be standing when they break.", ja = "" },  -- TODO
    ["line.conversation_hunters_lodge_slot_02_confront.3"] = { en = "Hold. When it is quiet, we will talk about what you are really hunting.", ja = "" },  -- TODO
    ["line.conversation_hunters_lodge_slot_02_join.1"] = { en = "You lived. Good. Most of the Lodge's people would not have. They come out here to take, and the wood knows the difference.", ja = "" },  -- TODO
    ["line.conversation_hunters_lodge_slot_02_join.2"] = { en = "The thing hollowing this place out was a hunter once. The greatest they ever had. Hunt the sacred long enough and you become it. That is the honor they were saving for me, though none of them would say so.", ja = "" },  -- TODO
    ["line.conversation_hunters_lodge_slot_02_join.3"] = { en = "{name}. I take only what I need, and it has kept me myself. But the wood I am part of is being devoured, and enough is the only thing that ever stops that kind of hunger. No outsider reaches the heart of it alone. I will lead you.", ja = "" },  -- TODO
    ["line.conversation_hunters_lodge_slot_02_join.4"] = { en = "Then lead. We'll take only what the wood can spare.", ja = "" },  -- TODO
    ["line.conversation_hunters_lodge_slot_02_join.5"] = { en = "See that you do. It is watching.", ja = "" },  -- TODO
    ["line.conversation_hunters_lodge_slot_10_confront.1"] = { en = "Another hunter, come to the heart of my wood. Good. I am always hungry, little sister, and you smell like one of us.", ja = "" },  -- TODO
    ["line.conversation_hunters_lodge_slot_10_confront.2"] = { en = "Stay. Trade blows with me. Every one you land, I take back twofold, and every one I land, I keep. Hunt me the long way, the way you were taught, and you will feed me until there is nothing of you left. There is no bottom to it. Take the crown, and you never have to stop.", ja = "" },  -- TODO
    ["line.conversation_hunters_lodge_slot_10_confront.3"] = { en = "I know exactly what you are offering. I have always known. It is the one thing I have spent my life refusing.", ja = "" },  -- TODO
    ["line.conversation_hunters_lodge_slot_10_confront.4"] = { en = "One shot. What the wood needs, and no more. Then I lay the bow down.", ja = "" },  -- TODO
    ["line.conversation_hunters_lodge_vendor_intro.1"] = { en = "The Lodge. We clear the beasts that would eat your children and feed your town on what's left. Honest work, honest coin. The board's always open. Take a bounty, take a trophy.", ja = "" },  -- TODO
    ["line.conversation_hunters_lodge_vendor_intro.2"] = { en = "Always open. It never closes?", ja = "" },  -- TODO
    ["line.conversation_hunters_lodge_vendor_intro.3"] = { en = "The wild always makes more game. That is the mercy of it. There is always another beast worth killing. Rank up, and one day you'll be a Grand Hunter, and they'll carve your name on the wall.", ja = "" },  -- TODO
    ["line.conversation_hunters_lodge_vendor_intro.4"] = { en = "I have read the names on that wall. Some of them I hunted.", ja = "" },  -- TODO
    ["line.conversation_hunters_lodge_vendor_intro.5"] = { en = "...You take only what you need, girl. That is why we could never crown you. You were the finest tracker the wood ever grew.", ja = "" },  -- TODO
    ["line.conversation_hunters_lodge_vendor_intro.6"] = { en = "It is why the wood never turned on me. Sell {name} the bows. Keep the crown.", ja = "" },  -- TODO
    ["line.conversation_hunters_lodge_vendor_intro.7"] = { en = "As you like. The board's open. There's always another beast worth killing.", ja = "" },  -- TODO
    ["line.conversation_prologue_arrival.1"] = { en = "There it is. Walls still standing, gates still shut. The capital.", ja = "" },  -- TODO
    ["line.conversation_prologue_arrival.10"] = { en = "It's been like this for weeks. The demons push, a village burns, and everyone still breathing runs for the capital. The city's fit to burst, work's gone dry, and food with it.", ja = "" },  -- TODO
    ["line.conversation_prologue_arrival.11"] = { en = "But coin still moves for those who can hold a blade. Register with the Adventurers' Guild. The quest board takes anyone who'll take a contract. Pays a good deal better than queuing for bread.", ja = "" },  -- TODO
    ["line.conversation_prologue_arrival.12"] = { en = "Work that pays. That, we can do.", ja = "" },  -- TODO
    ["line.conversation_prologue_arrival.13"] = { en = "The board, then. We'll want coin before we want anything else.", ja = "" },  -- TODO
    ["line.conversation_prologue_arrival.14"] = { en = "I am the baron of Bellmere's child. The town burned four nights ago.", ja = "" },  -- TODO
    ["line.conversation_prologue_arrival.15"] = { en = "Bellmere. That's the whole eastern line gone, then.", ja = "" },  -- TODO
    ["line.conversation_prologue_arrival.2"] = { en = "The Bastion holds this wall. If anywhere is still holding, {name}, it is behind these stones.", ja = "" },  -- TODO
    ["line.conversation_prologue_arrival.3"] = { en = "More of them. Third column through the gate since morning. Where are we meant to put them all?", ja = "" },  -- TODO
    ["line.conversation_prologue_arrival.4"] = { en = "Not under my roof, that's certain. Barely bread enough for the mouths already inside.", ja = "" },  -- TODO
    ["line.conversation_prologue_arrival.5"] = { en = "You there. Off the road, with the others. Nobody passes until they're processed. Names, and where you've run from.", ja = "" },  -- TODO
    ["line.conversation_prologue_arrival.6"] = { en = "Papers, a token, a seal, anything to say who you are. No? Then you'll wait like the rest of them until I say oth--", ja = "" },  -- TODO
    ["line.conversation_prologue_arrival.7"] = { en = "...That plate. That's Bastion steel. You're a sworn knight of the Order?", ja = "" },  -- TODO
    ["line.conversation_prologue_arrival.8"] = { en = "I held the eastern wall. The wall is ash now. I brought out who I could.", ja = "" },  -- TODO
    ["line.conversation_prologue_arrival.9"] = { en = "Forgive me, ser. We don't see many of the Order come through on foot these days. Pass. You, and the ones at your back.", ja = "" },  -- TODO
    ["line.conversation_prologue_flee.1"] = { en = "I can still see the hall from here. All of it is still burning.", ja = "" },  -- TODO
    ["line.conversation_prologue_flee.10"] = { en = "Not this ground. It was never the ground. We go to the capital while its walls are still standing.", ja = "" },  -- TODO
    ["line.conversation_prologue_flee.11"] = { en = "Your father. Ellis. Odo at the bell, where you would expect him. I could not reach that side of the town in time.", ja = "" },  -- TODO
    ["line.conversation_prologue_flee.2"] = { en = "I went back through the east quarter, {name}. There is nobody left to bring out.", ja = "" },  -- TODO
    ["line.conversation_prologue_flee.4"] = { en = "You were told to keep me alive. You kept me alive.", ja = "" },  -- TODO
    ["line.conversation_prologue_flee.5"] = { en = "I was charged with the body of a baron's child, and that is the whole of what I did tonight.", ja = "" },  -- TODO
    ["line.conversation_prologue_flee.6"] = { en = "The man who charged me is dead. The house that paid the Order is ash. There is nothing standing over me now.", ja = "" },  -- TODO
    ["line.conversation_prologue_flee.7"] = { en = "So I will say one of my own. It is two words.", ja = "" },  -- TODO
    ["line.conversation_prologue_flee.8"] = { en = "We shall hold.", ja = "" },  -- TODO
    ["line.conversation_prologue_flee.9"] = { en = "Hold what? There is nothing here left to hold.", ja = "" },  -- TODO
    ["line.conversation_prologue_flier.1"] = { en = "Bounties, escorts, standing contracts... half of these want a company three times our size.", ja = "" },  -- TODO
    ["line.conversation_prologue_flier.2"] = { en = "This one doesn't.", ja = "" },  -- TODO
    ["line.conversation_prologue_flier.3"] = { en = "The Colosseum. A debut bout, a single fight on the sand, in front of a crowd.", ja = "" },  -- TODO
    ["line.conversation_prologue_flier.4"] = { en = "A blood sport. Is this what we're reduced to?", ja = "" },  -- TODO
    ["line.conversation_prologue_flier.5"] = { en = "Pride has buried more soldiers than the demons have, {name}. I'll not let it bury us. We earn today, we eat tonight, and we choose our war when we can.", ja = "" },  -- TODO
    ["line.conversation_prologue_intro.1"] = { en = "Father wants the whole house at the table tonight, before the roads close.", ja = "" },  -- TODO
    ["line.conversation_prologue_intro.10"] = { en = "Ellis will bring them out. Stay at my shoulder and do what I tell you.", ja = "" },  -- TODO
    ["line.conversation_prologue_intro.2"] = { en = "He'll say that, and then he'll eat where he always eats. At his desk.", ja = "" },  -- TODO
    ["line.conversation_prologue_intro.3"] = { en = "Then we sit and wait for him, {name}. Both of us. I am not doing it on my own.", ja = "" },  -- TODO
    ["line.conversation_prologue_intro.4"] = { en = "Ser Rowan. {name}. There is fire on the eastern fields!", ja = "" },  -- TODO
    ["line.conversation_prologue_intro.5"] = { en = "Not one rick burning. The whole line of them, from the mill road down to the east wall.", ja = "" },  -- TODO
    ["line.conversation_prologue_intro.6"] = { en = "That is an army. The Demon Lord's people burn a valley from its edge inward.", ja = "" },  -- TODO
    ["line.conversation_prologue_intro.7"] = { en = "I'll get father and the household onto the west road. Ring the bell, Odo, and keep ringing it.", ja = "" },  -- TODO
    ["line.conversation_prologue_intro.8"] = { en = "The east wall is nearest and it is thinnest. {name}, with me. We hold the lane while the town empties.", ja = "" },  -- TODO
    ["line.conversation_prologue_intro.9"] = { en = "And the house?", ja = "" },  -- TODO
    ["line.conversation_prologue_ruins.2"] = { en = "Many did. We held that gate long enough for them to run.", ja = "" },  -- TODO
    ["line.conversation_prologue_ruins.3"] = { en = "Look down the valley, {name}. Those villages burned too, with no one to hold a gate. Survivors will be hiding in the hills.", ja = "" },  -- TODO
    ["line.conversation_prologue_ruins.4"] = { en = "Then let's find them.", ja = "" },  -- TODO
    ["line.conversation_prologue_ruins.5"] = { en = "Good! We take the king's road to the capital, {name}. We'll be safe behind its walls, and we save anyone we can along the way.", ja = "" },  -- TODO
    ["line.conversation_prologue_ruins.6"] = { en = "Bellmere is gone. I don't know who else made it out.", ja = "" },  -- TODO
    ["line.conversation_prologue_village.2"] = { en = "This is not a raid. The Demon Lord's army empties whole valleys like this and moves on before the ash is cold.", ja = "" },  -- TODO
    ["line.conversation_prologue_village.3"] = { en = "Two of them have seen us, and they will not come to you. Watch how I take mine.", ja = "" },  -- TODO
    ["line.conversation_prologue_village.4"] = { en = "Look at it, {name}. The market row, the bell tower, the gate your father set the first stone in. All of it, inside a night.", ja = "" },  -- TODO
    ["line.conversation_tutorial_flight.1"] = { en = "Walk to the chest ahead. Use WASD, the arrow keys, or click a tile.", ja = "" },  -- TODO
    ["line.conversation_tutorial_flight.2"] = { en = "Open your loadout to see what you found.", ja = "" },  -- TODO
    ["line.conversation_tutorial_flight.3"] = { en = "{select} an item in your stash to equip it to a hero.", ja = "" },  -- TODO
    ["line.conversation_tutorial_village.1"] = { en = "Close the distance and strike without fear, {name}!", ja = "" },  -- TODO
    ["line.conversation_tutorial_village.10"] = { en = "{select} on the lit tile to move there.", ja = "" },  -- TODO
    ["line.conversation_tutorial_village.11"] = { en = "{select} on Clear Out in your grid to ready it.", ja = "" },  -- TODO
    ["line.conversation_tutorial_village.12"] = { en = "{select} on your own tile to spin.", ja = "" },  -- TODO
    ["line.conversation_tutorial_village.13"] = { en = "{select} on Jolt to ready it. Its cost is purple: that is mana, not stamina.", ja = "" },  -- TODO
    ["line.conversation_tutorial_village.14"] = { en = "{select} on the grunt to jolt it.", ja = "" },  -- TODO
    ["line.conversation_tutorial_village.15"] = { en = "{select} on the grunt to strike it. Its card slid down the order, so you act before it does.", ja = "" },  -- TODO
    ["line.conversation_tutorial_village.2"] = { en = "There's more to the north. Slay them both before they do even more damage.", ja = "" },  -- TODO
    ["line.conversation_tutorial_village.3"] = { en = "Now take it in hand.", ja = "" },  -- TODO
    ["line.conversation_tutorial_village.4"] = { en = "Turn on your heel, {name}. Open them both at once.", ja = "" },  -- TODO
    ["line.conversation_tutorial_village.5"] = { en = "That big one is about to strike, use your magic, {name}!", ja = "" },  -- TODO
    ["line.conversation_tutorial_village.6"] = { en = "Let it have the spark. It will not know which way it is facing.", ja = "" },  -- TODO
    ["line.conversation_tutorial_village.7"] = { en = "While it's stunned, {name}. Let's finish this!", ja = "" },  -- TODO
    ["line.conversation_tutorial_village.8"] = { en = "Not that, {name}. Do as I showed you.", ja = "" },  -- TODO
    ["line.conversation_tutorial_village.9"] = { en = "{select} on the imp to move in range and attack with your weapon.", ja = "" },  -- TODO
    ["line.conversation_undercroft_discipline_unlocked.1"] = { en = "The {discipline}'s trade is yours now, {name}. The firm keeps stock off the open book for a hand that reaches it, and you reached it. Quietly, mind.", ja = "" },  -- TODO
    ["line.conversation_undercroft_discipline_unlocked.2"] = { en = "Then it's earned. Show me.", ja = "" },  -- TODO
    ["line.conversation_undercroft_discipline_unlocked.3"] = { en = "Took me years to get shown that rack. You did it faster. Don't get sloppy with it.", ja = "" },  -- TODO
    ["line.conversation_undercroft_slot_02_confront.1"] = { en = "That one there is ours. Was ours. Best hand we ever ran, and now she burns our writs and walks our debtors out the back. Theft, plain theft. Collect her.", ja = "" },  -- TODO
    ["line.conversation_undercroft_slot_02_confront.2"] = { en = "Collect me. Listen to the word he uses. Everyone on this floor is a note to him. Including you, the second you can't pay.", ja = "" },  -- TODO
    ["line.conversation_undercroft_slot_02_confront.3"] = { en = "I cut throats for that ledger for years. Now I burn it. If you were sent to bring me in, come on, but you'll have seen what I am first.", ja = "" },  -- TODO
    ["line.conversation_undercroft_slot_02_join.1"] = { en = "You had me, and you didn't cash me in. Do you know how rare that is, down here? Nobody does a thing for nothing. That's the whole disease.", ja = "" },  -- TODO
    ["line.conversation_undercroft_slot_02_join.2"] = { en = "The guild's the Bank's knife, and the Bank owns the government it bought the laws from. The debt isn't the gold. It's the way everyone's been taught to think. I can't kill an idea. But I can burn the paper, and walk the ruined out.", ja = "" },  -- TODO
    ["line.conversation_undercroft_slot_02_join.3"] = { en = "{name}. Every kill I take, I turn into everyone's tempo and keep none. That's the only way I know to pay down what I did with the same hands. Let me spend it on your road. I'll cost you nothing.", ja = "" },  -- TODO
    ["line.conversation_undercroft_slot_02_join.4"] = { en = "You'll cost us nothing, and we'll owe you plenty. Walk with us.", ja = "" },  -- TODO
    ["line.conversation_undercroft_slot_02_join.5"] = { en = "...Owe me nothing. That's the point. But yes. Let's go.", ja = "" },  -- TODO
    ["line.conversation_undercroft_slot_10_confront.1"] = { en = "My best blade, come home at last. I hold every note in this city, Clem. The almshouse, the crown's war, and yours. You never could forgive your own debt. I can. Kneel, and I mark it paid.", ja = "" },  -- TODO
    ["line.conversation_undercroft_slot_10_confront.2"] = { en = "Take my gold and you take everything I lift off them. Gild your friends, empty their hands, and you will never want again. It is the one thing I have that no one can call in. Be owed, instead of owing. Be free.", ja = "" },  -- TODO
    ["line.conversation_undercroft_slot_10_confront.3"] = { en = "You'd absolve me, so I'd owe you the absolution forever. I know that trick. I taught it.", ja = "" },  -- TODO
    ["line.conversation_undercroft_slot_10_confront.4"] = { en = "I don't need your hand to clear it. I'll forgive myself, for free, and burn every note in your vault on the way out. The city's paid. Keep the crown that starves you.", ja = "" },  -- TODO
    ["line.conversation_undercroft_vendor_intro.1"] = { en = "No sign, no door you'd notice. Good. You found us anyway. The Undercroft looks after its own, friend. Debts, and the quiet murder of the people who won't pay them. Everything on this floor belonged to someone else once. That's just business.", ja = "" },  -- TODO
    ["line.conversation_undercroft_vendor_intro.2"] = { en = "And the people it belonged to?", ja = "" },  -- TODO
    ["line.conversation_undercroft_vendor_intro.3"] = { en = "Owed. Everyone's owed, up above. Your house, your city's water, your king's war. We just hold the note. A debt is a debt. That's not cruelty, that's the world.", ja = "" },  -- TODO
    ["line.conversation_undercroft_vendor_intro.4"] = { en = "I used to say that word for word. I collected on it, too. That's the lie. 'we look after our own,' over a floor that owns every soul on it.", ja = "" },  -- TODO
    ["line.conversation_undercroft_vendor_intro.5"] = { en = "Clem. You were the best blade we ever ran. Then you started burning the paper.", ja = "" },  -- TODO
    ["line.conversation_undercroft_vendor_intro.6"] = { en = "I started reading it. Sell {name} the kit. Keep the family.", ja = "" },  -- TODO
    ["line.conversation_undercroft_vendor_intro.7"] = { en = "As you like. Floor's open. Everything's for sale, and everything's owed.", ja = "" },  -- TODO
